var recordingTranscript = [
  {
    "time": 326,
    "speaker": "\u6559\u5E08",
    "text": "\u5404\u4F4D\u540C\u5B66\u4E0B\u5348\u597D\uFF0C\u6211\u4EEC\u73B0\u5728\u5F00\u59CB\u4E0A\u8BFE\u3002\u5443\uFF0C\u6B22\u8FCE\u5927\u5BB6\u6765\u5230\u667A\u6167\u533B\u7597\u521B\u65B0\u4F53\u9A8C\uFF0C\u8FD9\u662F\u6211\u4EEC\u7684\u7B2C\u4E8C\u6B21\u8BFE\u3002\u7136\u540E\u6211\u4EEC\u8FD9\u8282\u8BFE\u8BB2\u4EBA\u5DE5\u667A\u80FD\u63A2\u79D8\uFF0C\u6211\u4EEC\u8FD8\u6709\u4E09\u8282\u8BFE\u7684\u65F6\u95F4\u3002\u6240\u4EE5\u8BF7\u5404\u4F4D\u540C\u5B66\u5408\u7406\u5B89\u6392\u597D\u65F6\u95F4\u54C8\u3002\u6211\u4EEC\u4ECA\u5929\u8BB2\u7684\u8FD9\u4E2A\u5185\u5BB9\u54C8\u3002\u56E0\u4E3A\u4EBA\u5DE5\u667A\u80FD\u662F\u6211\u4EEC\u8FD9\u4E2A\u667A\u80FD\u533B\u5B66\u7684\u91CD\u8981\u7EC4\u6210\u90E8\u5206\u3002\u4F46\u5B9E\u9645\u4E0A\u4EBA\u5DE5\u667A\u80FD\u53D1\u5C55\u7684\u5386\u7A0B\u5F88\u957F\uFF0C\u5185\u5BB9\u4E5F\u5F88\u591A\u3002\u90A3\u6211\u4EEC\u5728\u8FD9\u6837\u4E00\u8282\u8BFE\u91CC\u8BB2\u6E05\u5F88\u591A\u4E1C\u897F\u662F\u4E0D\u73B0\u5B9E\u7684\u3002"
  },
  {
    "time": 360,
    "speaker": "\u6559\u5E08",
    "text": "\u4F46\u662F\u6211\u4EEC\u91CD\u8981\u7684\u662F\u8981\u628A\u91CC\u8FB9\u7684\u4E00\u4E9B\u601D\u60F3\u8FDB\u884C\u6574\u4F53\u6027\u7684\u8BA4\u77E5\u3002\u8BB2\u7ED9\u5927\u5BB6\u3002\u90A3\u6240\u4EE5\u5462\u6211\u4EEC\u4F1A\u5206\u6210\u4E09\u4E2A\u90E8\u5206\uFF0C\u7B2C\u4E00\u4E2A\u662F\u4EBA\u5DE5\u667A\u80FD\u7684\u5386\u7A0B\u3002\u7136\u540E\u4ECE\u77E5\u8BC6\u9A71\u52A8\u5230\u6570\u636E\u9A71\u52A8\uFF0C\u518D\u5230\u63A5\u4E0B\u6765\u4E0D\u8FDC\u7684\u672A\u6765\u3002\u56E0\u4E3A\u4EBA\u5DE5\u667A\u80FD\u53D1\u5C55\u5F97\u5F88\u5FEB\u3002\u63A5\u4E0B\u6765\u4E0D\u8FDC\u7684\u672A\u6765\u5C31\u4F1A\u53D1\u751F\u4E00\u4E9B\u65B0\u7684\u53D8\u5316\u3002\u6211\u4EEC\u73B0\u5728\u540C\u5B66\u4EEC\u90FD\u65F6\u65F6\u523B\u523B\u5728\u7528\u7684\u5927\u8BED\u8A00\u6A21\u578B\uFF0C\u5BF9\u5427\uFF1F\u90A3\u5B83\u5C5E\u4E8E\u901A\u7528\u4EBA\u5DE5\u667A\u80FD\u91CC\u6700\u521D\u7684\u4E00\u5757\u91CC\u7A0B\u7891\u3002"
  },
  {
    "time": 393,
    "speaker": "\u6559\u5E08",
    "text": "\u90A3\u6211\u4EEC\u628A\u5B83\u53EB\u505A\u4E00\u4E2A\u706B\u82B1\uFF0C\u5B83\u4E5F\u5E76\u6CA1\u6709\u5B8C\u6574\u5730\u5B9E\u73B0\u901A\u7528\u4EBA\u5DE5\u667A\u80FD\u3002\u4F46\u662F\u5B83\u5BF9\u6211\u4EEC\u7684\u751F\u6D3B\u5DF2\u7ECF\u4EA7\u751F\u4E86\u5F88\u5927\u7684\u53D8\u5316\uFF0C\u6240\u6709\u7684\u4EA7\u4E1A\u3002\u6240\u6709\u7684\u4EBA\u90FD\u5728\u8003\u8651\u5982\u4F55\u5E94\u7528\u5B83\uFF0C\u63D0\u5347\u81EA\u5DF1\u3002\u90A3\u7B2C\u4E09\u8282\u8BFE\u6211\u4EEC\u8FDB\u884C\u4E00\u4E2A\u5C0F\u7EC4\u8BA8\u8BBA\u3002\u6211\u4EEC\u4E0A\u8282\u8BFE\u540C\u5B66\u4EEC\u8BFE\u540E\u4E5F\u505A\u8FC7\u4E00\u4E9B\u884C\u4E1A\u8C03\u7814\u3002\u90A3\u6211\u4EEC\u5E0C\u671B\u5927\u5BB6\u901A\u8FC7\u5C0F\u7EC4\u8BA8\u8BBA\u7684\u65B9\u5F0F\uFF0C\u5C31\u884C\u4E1A\u3002\u8FD8\u6709\u524D\u6CBF\u7684\u667A\u80FD\u6280\u672F\u5728\u7EC4\u5185\u5206\u4EAB\uFF0C\u518D\u8DDF\u5168\u73ED\u5206\u4EAB\u4E00\u4E0B\u3002"
  },
  {
    "time": 427,
    "speaker": "\u6559\u5E08",
    "text": "\u90A3\u6211\u4EEC\u5148\u770B\u4E00\u770B\u8FD9\u4E2A\u8BFE\u7A0B\u7684\u7531\u6765\u3002\u6211\u4EEC\u4E3A\u4EC0\u4E48\u8BB2\u4EBA\u5DE5\u667A\u80FD\u63A2\u79D8\uFF0C\u533B\u5B66\u73B0\u5728\u5927\u6982\u5206\u6210\u4E86\u4E09\u4E2A\u65F6\u4EE3\u3002\u7B2C\u4E00\u4E2A\u65F6\u4EE3\u662F\u7ECF\u9A8C\u533B\u5B66\uFF0C\u7B2C\u4E8C\u4E2A\u65F6\u4EE3\u662F\u5FAA\u8BC1\u533B\u5B66\u3002\u7B2C\u4E09\u4E2A\u65F6\u4EE3\u662F\u667A\u80FD\u533B\u5B66\uFF0C\u4E5F\u5C31\u662F\u73B0\u5728\u6211\u4EEC\u8FD9\u4E2A\u9636\u6BB5\u3002\u90A3\u6559\u80B2\u90E8\u5F53\u65F6\u4E5F\u63D0\u51FA\u6765\u4E86\u65B0\u533B\u79D1\u4E0E\u533B\u5DE5\u4EA4\u53C9\u3002\u5C31\u662F\u8FD9\u79CD\u6559\u80B2\u5176\u5B9E\u4E00\u76F4\u5728\u53D8\uFF0C\u8FD9\u4E5F\u5C31\u662F\u8BFE\u4E0A\u3002\u6211\u4EEC\u4E5F\u8BF4\u8FC7\uFF0C\u5927\u5BB6\u4E00\u5B9A\u8981\u6210\u4E3A\u521B\u65B0\u6027\u4EBA\u624D\uFF0C\u800C\u4E0D\u662F\u6548\u7387\u6027\u4EBA\u624D\u3002\u6211\u4EEC\u6559\u7684\u5185\u5BB9\u90FD\u5728\u53D8\u3002"
  },
  {
    "time": 459,
    "speaker": "\u6559\u5E08",
    "text": "\u6240\u4EE5\u4E5F\u8BB8\u4F60\u4EEC\u6BD5\u4E1A\u4E4B\u540E\u4E0D\u4E45\uFF0C\u63A5\u4E0B\u6765\u7684\u5E08\u5F1F\u5E08\u59B9\u5B66\u7684\u4E1C\u897F\u5C31\u4F1A\u53D8\u3002\u5C31\u50CF\u4F60\u4EEC\u73B0\u5728\u4E0A\u5B66\u5B66\u7684\u5185\u5BB9\uFF0C\u6211\u539F\u6765\u4E0A\u5B66\u7684\u65F6\u5019\u6CA1\u5B66\u8FC7\u6211\u5B66\u7684\u5185\u5BB9\u3002\u73B0\u5728\u5DF2\u7ECF\u4E0D\u6559\u4E86\u3002\u90A3\u6240\u4EE5\u4F60\u8981\u4E0D\u65AD\u5730\u81EA\u4E3B\u5B66\u4E60\u3002\u627E\u5230\u9002\u5408\u81EA\u5DF1\u7684\u5B66\u4E60\u65B9\u5F0F\u3002\u90A3\u4E482019\u5E74\u6211\u4EEC\u4E5F\u54CD\u5E94\u6559\u80B2\u90E8\u7684\u8FD9\u4E2A\u65B9\u5411\u3002\u7136\u540E\u5F00\u8BBE\u4E86\u667A\u6167\u533B\u7597\u521B\u65B0\u4F53\u9A8C\u3002\u8FD9\u6837\u4E00\u95E8\u8BFE\u4E3B\u8981\u662F\u628A\u91CC\u8FB9\u7684\u667A\u80FD\u533B\u5B66\u6280\u672F\u539F\u7406\u548C\u533B\u52A1\u8C03\u67E5\u7684\u521B\u65B0\u65B9\u6CD5\u8FDB\u884C\u8BB2\u6388\u3002"
  },
  {
    "time": 494,
    "speaker": "\u6559\u5E08",
    "text": "\u597D\uFF0C\u90A3\u6211\u4EEC\u5728\u8BB2\u4EBA\u5DE5\u667A\u80FD\u63A2\u79D8\u4E4B\u524D\uFF0C\u5148\u56DE\u987E\u4E00\u4E0B\u3002\u56E0\u4E3A\u6709\u4E24\u5468\u7684\u65F6\u95F4\uFF0C\u5927\u5BB6\u53EF\u80FD\u6709\u70B9\u5FD8\u4E86\u667A\u6167\u533B\u7597\u7B80\u53F2\u3002\u6211\u4EEC\u5F53\u65F6\u8BF4\u4EE5\u53F2\u89C1\u4ECA\uFF0C\u8FD8\u662F\u901A\u8FC7\u5386\u53F2\u6765\u4E86\u89E3\u8FD9\u4E2A\u601D\u8DEF\u3002\u6211\u4EEC\u8BB2\u4E86\u4E00\u7CFB\u5217\u7684\u6848\u4F8B\uFF0C\u5176\u5B9E\u90FD\u5728\u8BF4\u660E\u6280\u672F\u4E0E\u95EE\u9898\u4E0D\u65AD\u5C1D\u8BD5\u3002\u7ED3\u5408\u8FD9\u6837\u7684\u4E00\u4E2A\u63A2\u7D22\u8FC7\u7A0B\u3002\u6BD4\u5982\u8BF4\u6570\u7406\u7EDF\u8BA1\u548C\u970D\u4E71\uFF0C\u7136\u540E\u8FD8\u6709MYCIN\u8FD9\u6837\u7684\u4E13\u5BB6\u7CFB\u7EDF\u3002\u8FD8\u6709\u8D1D\u53F6\u65AF\u548C\u5185\u79D1\u8BCA\u65AD\u3002\u90A3\u4E48\u673A\u5668\u5B66\u4E60\u3001\u6C83\u68EE\u533B\u751F\u90FD\u662F\u628A\u5F53\u524D\u7684\u6280\u672F\u548C\u6700\u65B0\u7684\u95EE\u9898\u7ED3\u5408\u5728\u4E00\u8D77\u3002"
  },
  {
    "time": 531,
    "speaker": "\u6559\u5E08",
    "text": "\u90A3\u4E48\u667A\u6167\u533B\u7597\u7684\u6982\u5FF5\u662F\u65B0\u4E00\u4EE3\u7684\u4FE1\u606F\u6280\u672F\u3002\u8FD9\u4E2A\u8BF4\u6CD5\u539F\u5219\u4E0A\u662F\u51C6\u786E\u7684\u3002\u4F46\u662F\u5185\u6DB5\u975E\u5E38\u4E30\u5BCC\uFF0C\u8FD9\u4E2A\u65B0\u4E00\u4EE3\u8981\u8DDF\u5168\u65B9\u4F4D\u3001\u5168\u65F6\u7A7A\u7684\u533B\u7597\u5065\u5EB7\u573A\u666F\u3002\u7ED3\u5408\uFF0C\u5B83\u7684\u4F18\u52BF\u662F\u5BF9\u533B\u751F\u3001\u62A4\u58EB\u3001\u60A3\u8005\u3001\u673A\u6784\u548C\u793E\u4F1A\u8FDB\u884C\u5168\u65B9\u4F4D\u7684\u63D0\u5347\u3002\u90A3\u4E48\u667A\u6167\u533B\u7597\u7684\u672C\u8D28\u662F\u5B66\u4E60\u6027\u3001\u8FC5\u901F\u6027\u3001\u51C6\u786E\u6027\u3002"
  },
  {
    "time": 561,
    "speaker": "\u6559\u5E08",
    "text": "\u5F53\u4F60\u7528\u4E00\u4E2A\u6280\u672F\u7684\u65F6\u5019\uFF0C\u4F60\u8981\u6E05\u695A\u5B83\u7684\u672C\u6027\u662F\u5426\u5339\u914D\u3002\u90A3\u80AF\u5B9A\u5C31\u662F\u5F3A\u8C03\u5339\u914D\u6027\u3002\u4E0D\u5339\u914D\uFF0C\u4F60\u8FD8\u5F97\u91CD\u65B0\u53D1\u5C55\u3002\u90A3\u6211\u4EEC\u540C\u5B66\u4E5F\u8FDB\u884C\u4E86\u4E00\u4E2A\u81EA\u6211\u4ECB\u7ECD\u3002\u76EE\u7684\u5176\u5B9E\u662F\u4E3A\u4E86\u53C2\u4E0E\u8DE8\u5B66\u79D1\u7684\u56E2\u961F\u5B66\u4E60\uFF0C\u5B66\u4F1A\u5982\u4F55\u4E0E\u4E0D\u540C\u80CC\u666F\u7684\u4E13\u4E1A\u4EBA\u5458\u8FDB\u884C\u5408\u4F5C\u3002\u4F60\u5F97\u4E86\u89E3\u4ED6\u4EEC\uFF0C\u77E5\u9053\u4ED6\u4EEC\u77E5\u9053\u4EC0\u4E48\u3001\u4E0D\u77E5\u9053\u4EC0\u4E48\uFF0C\u8FD9\u662F\u975E\u5E38\u91CD\u8981\u7684\u3002\u4ED6\u4EEC\u64C5\u957F\u4EC0\u4E48\u3001\u559C\u6B22\u4EC0\u4E48\uFF0C\u8FD9\u975E\u5E38\u91CD\u8981\u3002\u90A3\u4E48\u6211\u4EEC\u4E00\u4E0A\u8BFE\u7684\u65F6\u5019\u4E5F\u8BF4\u8FC7\u8FD9\u4E2AAI\u52A9\u5B66\u3002"
  },
  {
    "time": 592,
    "speaker": "\u6559\u5E08",
    "text": "\u90A3\u6211\u4EEC\u6709\u8BFE\u5802\u91CC\u7684AI24\u5C0F\u65F6\u5B66\u4E60\u52A9\u624B\u3002\u8FD8\u6709AI\u8FD9\u6837\u4E00\u4E2A\u5E73\u53F0\uFF0C\u53EF\u4EE5\u505A\u8D44\u6599\u67E5\u8BE2\u548C\u521B\u65B0\u5F00\u53D1\u3002\u90A3\u6211\u4EEC\u4ECE\u6559\u80B2\u7684\u89D2\u5EA6\u6765\u770B\u4E00\u770B\u6211\u4EEC\u8FD9\u4E2A\u8BFE\u3002\u6211\u4EEC\u4E00\u76F4\u5728\u7528\u4EBA\u5DE5\u667A\u80FD\u8D4B\u80FD\u6559\u80B2\uFF0C\u770B\u8FD9\u4E9B\u7167\u7247\u3002\u5C31\u662F\u5927\u5BB6\u73B0\u5728\u6240\u5728\u6559\u5BA4\u7684\u7167\u7247\uFF0C\u524D\u9762\u6709\u5BF9\u7740\u5B66\u751F\u7684\u6444\u50CF\u5934\u3002\u90A3\u8FB9\u6709\u5BF9\u7740\u8001\u5E08\u7684\u6444\u50CF\u5934\uFF0C\u80FD\u591F\u968F\u52A8\u62CD\u6444\u3002\u7136\u540E\u8FD8\u6709\u5F55\u64AD\u4E3B\u673A\u3002\u8FD8\u6709\u8BFE\u5802\u5206\u6790\u7CFB\u7EDF\u90FD\u5728\u8FDB\u884C\u5206\u6790\u3002"
  },
  {
    "time": 623,
    "speaker": "\u6559\u5E08",
    "text": "\u6240\u4EE5\u6211\u4EEC\u7684\u8BFE\u7A0B\u6570\u636E\u4F1A\u6E90\u6E90\u4E0D\u65AD\u5730\u88AB\u6536\u96C6\u8FDB\u6765\u3002\u90A3\u6211\u4EEC\u6536\u96C6\u8FDB\u6765\u540E\u5C31\u4F1A\u8FDB\u884C\u5206\u6790\uFF0C\u8FD9\u5C31\u662F\u7528AI\u8FDB\u884C\u7684\u5B66\u60C5\u5206\u6790\u3002\u5305\u62EC\u6211\u4EEC\u73B0\u572826\u4E2A\u4EBA\u6765\u81EA14\u4E2A\u9662\uFF0C\u7136\u540E\u94B1\u5B66\u68EE\u4E66\u9662\u7684\u540C\u5B66\u5C45\u591A\u3002\u67096\u4E2A\u4EBA\uFF0C\u81EA\u52A8\u5316\u7684\u67094\u4E2A\u4EBA\uFF0C\u751F\u547D\u5B66\u9662\u7684\u67094\u4E2A\u4EBA\u7B49\u7B49\u3002\u8FD8\u6709\u5F88\u591A\u5317\u5927\u7684\u9648\u745C\u540C\u5B66\u6765\u4E86\u5417\uFF1F\u4F60\u56DE\u5934\u8DDF\u8001\u5E08\u4EEC\u8BF4\u4E00\u4E0B\u4F60\u662F\u54EA\u4E2A\u9662\u7CFB\u7684\u54C8\u3002\u6211\u4EEC\u8FD9\u8FD8\u6CA1\u6709\u767B\u8BB0\u5230\u4F60\u7684\u4FE1\u606F\uFF0C\u5728\u7F51\u7EDC\u5B66\u5802\u90FD\u662F\u6559\u52A1\u5904\u3002"
  },
  {
    "time": 656,
    "speaker": "\u6559\u5E08",
    "text": "\u5927\u5BB6\u6709\u5404\u79CD\u5404\u6837\u7684\u89C9\u5F97\u9700\u6C42.\u7136\u540E\u7537\u5973\u751F\u7684\u6BD4\u4F8B\uFF0C\u7136\u540E\u8FD8\u6709iClass\u7684\u4F7F\u7528\u60C5\u51B5\u3002\u6211\u6CA1\u6709\u5443\uFF0C\u5927\u6982\u5927\u7EA6\u6709\u4E5D\u4F4D\u540C\u5B66\u7533\u8BF7\u5E76\u5F00\u59CB\u4F7F\u7528\u8FD9\u4E2A\u8D26\u53F7\u3002\u7136\u540E\u6709\u7684\u540C\u5B66\u3001\u50CF\u8303\u540C\u5B66\u3001\u91D1\u540C\u5B66\u3001\u674E\u540C\u5B66\u3001\u5F20\u540C\u5B66\u90FD\u4F7F\u7684\u6BD4\u8F83\u591A\uFF0C\u5F00\u59CB\u5728\u5C1D\u8BD5\u4F7F\u7528\u3002\u90A3\u8FD9\u5C31\u662F\u6211\u4EEC\u5BF9\u8FD9\u4E2A\u7684\u4E00\u4E2A\u5B66\u4E60\u5206\u6790\uFF0C\u518D\u901A\u8FC7\u5927\u5BB6\u5927\u5BB6\u662F\u7AD9\u5728\u53F0\u4E0A\u6765\u8BF4\u7684\u5BF9\u5427\uFF1F"
  },
  {
    "time": 687,
    "speaker": "\u6559\u5E08",
    "text": "\u8FD9\u4E2A\u540E\u53F0\u5C31\u8BC6\u522B\u51FA\u6765\u4E86\u3002\u6211\u4EEC\u53C8\u6839\u636E\u5927\u5BB6\u8BF4\u7684\uFF0C\u6BD4\u5982\u8BF4\u6211\u53EB\u5218\u4F73\u742A\uFF0C\u5BF9\u5427\uFF1F\u90A3\u597D\uFF0C\u90A3\u8FD9\u5757\u5C31\u88AB\u8BC6\u522B\u51FA\u5BF9\u5E94\u7740\u4F60\u7684\u5F55\u97F3\uFF0C\u4ED6\u4E0D\u77E5\u9053\u662F\u54EA\u4E09\u4E2A\u5B57\u3002\u4F46\u662F\u6211\u4EEC\u7ED9\u4E86\u4ED6\u7684\u5B66\u751F\u540D\u5355\uFF0C\u4ED6\u5C31\u80FD\u8BC6\u522B\u51FA\u6765\uFF0C\u8FD9\u662F\u54EA\u4E2A\u5BB6\u54EA\u4E2A\u9F50\uFF0C\u7136\u540E\u628A\u8FD9\u4E9B\u4E1C\u897F\u8FDB\u884C\u603B\u7ED3\u3002\u603B\u7ED3\u4E4B\u540E\uFF0C\u6211\u4EEC\u518D\u8981\u8FDB\u4E00\u6B65\u7684\u805A\u7C7B\uFF0C\u7136\u540E\u770B\u4E00\u770B\uFF0C\u901A\u8FC7\u63A8\u8350\u7684\uFF0C\u901A\u8FC7\u5BF9\u8FD9\u4E2A\u672C\u8EAB\u667A\u6167\u533B\u7597\u611F\u5174\u8DA3\u7684\u81EA\u5DF1\u5BF9\u8FD9\u4E2A\u9898\u76EE\u76F8\u5173\u7684\u3002"
  },
  {
    "time": 720,
    "speaker": "\u6559\u5E08",
    "text": "\u5728\u5E94\u7528\u7740\uFF0C\u8FD9\u662F\u6211\u4EEC\u80FD\u770B\u5230\u7684\u4E00\u4E2A\u4E5F\u662F\u8DDF\u540C\u5B66\u4EEC\u5206\u4EAB\uFF0C\u5E0C\u671B\u5927\u5BB6\u80FD\u4E0D\u65AD\u5730\u628Aai\u7528\u5230\u81EA\u5DF1\u7684\u5404\u79CD\u5404\u6837\u7684\u8FD9\u4E2A\u751F\u6D3B\u7EC6\u8282\u4E2D\u3002\u597D\uFF0C\u90A3\u6211\u4EEC\u56DE\u5230\u6211\u4EEC\u8FD9\u8282\u8BFE\u8981\u8BB2\u7684\u6B63\u9898\u4E0A\u8FB9\uFF0C\u90A3\u6211\u4EEC\u7684\u4EBA\u5DE5\u667A\u80FD\u7684\u5386\u7A0B\u4E03\u5341\u5E74\uFF0C\u5BF9\u5427\uFF1F\u4ECE\u4E94\u96F6\u5E74\u5230\u73B0\u5728\u5927\u6982\u4E03\u5341\u56DB\u5E74\uFF0C\u7C97\u7565\u8BA1\u7B97\uFF0C"
  },
  {
    "time": 751,
    "speaker": "\u6559\u5E08",
    "text": "\u90A3\u4E48\u6574\u4E2A\u8FD9\u4E2A\u8FC7\u7A0B\u6211\u4EEC\u53EF\u4EE5\u7B80\u5355\u7684\u7406\u89E3\u4E3A\u4ECE\u77E5\u8BC6\u9A71\u52A8\u5230\u6570\u636E\uFF0C\u63A5\u4E0B\u6765\u7684\u672A\u6765\u53EF\u80FD\u662F\u77E5\u8BC6\u52A0\u6570\u636E\u7684\u4E00\u79CD\u6DF7\u5408\u9A71\u52A8\u3002\u90A3\u6211\u4EEC\u8FD9\u8282\u8BFE\u7684\u8FD9\u4E2A\u5B89\u6392\u54C8\u662F\u5B89\u6392\u4E00\u6B21\u884C\u4E1A\u95EE\u9898\u7814\u8BA8\u3002\u7136\u540E\u8BFE\u540E\u7684\u4F5C\u4E1A\u5462\uFF0C\u4F1A\u6709\u4E2A\u4EBA\u667A\u6167\u533B\u7597\u76F8\u5173\u4F5C\u4E1A.\u90A3\u4E48\u5728\u4EBA\u5DE5\u667A\u80FD\u7684\u8FD9\u91CC\u8FB9\uFF0C\u6211\u4EEC\u9996\u5148\u770B\u5B66\u79D1\uFF0C"
  },
  {
    "time": 782,
    "speaker": "\u6559\u5E08",
    "text": "\u8FD9\u662F\u9762\u5411\u7814\u7A76\u751F\u4F1A\u6709\u8FD9\u6837\u4E94\u4E2A\u65B9\u5411\u3002\u90A3\u4E48\u7B2C\u4E00\u4E2A\u662F\u57FA\u7840\u7406\u8BBA\uFF0C\u8FD9\u91CC\u8FB9\u5F3A\u8C03\u6570\u5B66\u591A\u4E00\u4E9B\uFF0C\u5305\u62EC\u8FD9\u4E2A\u4F18\u5316\u7406\u8BBA\uFF0C\u6570\u5B66\u57FA\u7840\u673A\u5668\u5B66\u4E60\u7684\u7406\u8BBA\uFF0C\u8FD8\u6709\u8111\u79D1\u5B66\uFF0C\u8FD8\u6709\u7C7B\u8111\u7B49\u7B49\u3002\u7136\u540E\u5728\u4E0A\u8FB9\u5462\u6709\u5171\u6027\u6280\u672F\u652F\u6491\u6280\u672F\uFF0C\u5171\u6027\u6280\u672F\uFF0C\u8FD9\u662F\u5F88\u591A\u8BA1\u7B97\u673A\u7684\u4E0A\u5C42\u5E94\u7528\u90FD\u4F1A\u7528\u5230\u7684\u3002\u6BD4\u5982\u8BF4\u611F\u77E5\u89C6\u89C9\u3001\u81EA\u7136\u8BED\u8A00\u7406\u89E3\uFF0C"
  },
  {
    "time": 812,
    "speaker": "\u6559\u5E08",
    "text": "\u6240\u4EE5\u4F60\u5728\u8FD9\u4E2A\u9886\u57DF\u4E0A\u53BB\u505A\u7814\u7A76\uFF0C\u4F60\u7684\u5E94\u7528\u662F\u5176\u4E2D\u7684\u4E00\u4E2A\u6A21\u5757\uFF0C\u5C31\u662F\u4F60\u7684\u8F93\u51FA\u6210\u679C\u662F\u7ED9\u5404\u4E2A\u6A21\u5757\u513F\uFF0C\u5404\u4E2A\u4EA7\u54C1\u91CC\u9762\u90FD\u8D4B\u80FD\u540C\u6837\u7684\u6A21\u5757\u3002\u90A3\u4E48\u8FD8\u6709\u4E00\u4E9B\u652F\u6491\u6280\u672F\uFF0C\u8FD9\u91CC\u8FB9\u5C31\u662F\u8F6F\u786C\u4EF6\u3002\u90A3\u6BD4\u5982\u8BF4\u5178\u578B\u7684\u53D7\u5236\u7EA6\u7684\u82AF\u7247\uFF0C\u8FD8\u6709\u4E00\u4E9B\u64CD\u4F5C\u7CFB\u7EDF\u3002\u8FD8\u6709\u4E00\u4E9B\u8FD9\u4E2A\u50CFTensorFlow\u8FD9\u79CD\u67B6\u6784\uFF0C\u8FD9\u662F\u6211\u4EEC\u4E2D\u56FD\u4E00\u76F4\u5728\u8FD9\u79CD\u57FA\u7840\u7684\u4E0A\u6BD4\u8F83\u843D\u540E\u7684\u8DDF\u7F8E\u56FD\u6BD4\u8D77\u6765\u843D\u540E\u7684\u3002"
  },
  {
    "time": 843,
    "speaker": "\u6559\u5E08",
    "text": "\u56E0\u4E3A\u5728\u8FD9\u91CC\u8FB9\u79BB\u5E02\u573A\u66F4\u8FD1\uFF0C\u5927\u5BB6\u4E5F\u80FD\u66F4\u80FD\u770B\u5230\u4EA7\u54C1\u5BB9\u6613\u53D7\u4EBA\u77A9\u76EE\u3002\u91CC\u8FB9\u5305\u62EC\u8FD9\u4E2A\u667A\u6167\u533B\u7597\u3001\u667A\u80FD\u4EA4\u901A\u3001\u65E0\u4EBA\u9A7E\u9A76\u3001\u673A\u5668\u7FFB\u8BD1\u7B49\u7B49\u7B49\u7B49\u7B49\u5F88\u591A\u65B9\u5411\u3002\u90A3\u4E48\u8FD8\u6709\u5462\u5C31\u662F\u4EBA\u5DE5\u667A\u80FD\u6CBB\u7406\uFF0C\u8FD9\u4E5F\u4E0A\u8282\u8BFE\uFF0C\u6211\u4EEC\u8BF4\u5404\u4E2A\u5B66\u79D1\u7684\u4EBA\u90FD\u80FD\u5728\u8FD9\u91CC\u8FB9\u627E\u5230\u81EA\u5DF1\u7684\u4E00\u4E2A\u53D1\u6325\u3002\u90A3\u4E48\u57FA\u4E8E\u4EBA\u5DE5\u667A\u80FD\u91CC\u8FB9\u6709\u8DDF\u793E\u4F1A\u79D1\u5B66\u76F8\u5173\u7684\u91CC\u8FB9\u5305\u62EC\u4F26\u7406\u3001\u53EF\u4FE1\u3001\u5B89\u5168\u3001\u516C\u5E73\u6027\u3001\u9690\u79C1\u4FDD\u62A4\u7B49\u8FD9\u4E9B\u65B9\u5411\u3002"
  },
  {
    "time": 877,
    "speaker": "\u6559\u5E08",
    "text": "\u90A3\u6211\u4EEC\u4E3A\u4EC0\u4E48\u8981\u5B66\u4E60\u4EBA\u5DE5\u667A\u80FD\uFF1F\u6211\u4EEC\u662F\u628A\u5B83\u53D8\u6210\u4E00\u4E2A\u4E13\u4E1A\u53BB\u770B\uFF0C\u8FD8\u662F\u8BF4\u5B83\u7684\u901A\u8BC6\u5C5E\u6027\u3002\u90A3\u4E48\u50CF\u73B0\u5728\u9999\u6E2F\u5927\u5B66\uFF0C\u5B83\u8FD9\u4E2A\u901A\u8BC6\u8BFE\u7A0B\u5C31\u662F\u8BF4\u4E0D\u7BA1\u4EFB\u4F55\u4E13\u4E1A\uFF0C\u4ED6\u4EEC\u90FD\u8981\u5B66\u4E09\u95E8\uFF0C\u539F\u6765\u662F\u6570\u5B66\u548C\u82F1\u8BED\uFF0C\u73B0\u5728\u589E\u52A0\u4E86\u3002\u524D\u4E24\u5929\u6211\u53C8\u5F00\u4E86\u4E00\u4E2A\u4F1A\uFF0C\u4E5F\u662F\u5168\u56FD\u7684\u8001\u5E08\u4EEC\uFF0C\u9AD8\u6821\u8001\u5E08\u4EEC\u5728\u4E00\u8D77\u8BA8\u8BBA\u53EB\u4EBA\u5DE5\u667A\u80FD\u901A\u8BC6\uFF0C\u5E94\u8BE5\u5982\u4F55\u6E05\u534E\u7684\u8001\u5E08\u3002"
  },
  {
    "time": 911,
    "speaker": "\u6559\u5E08",
    "text": "\u6240\u4EE5\u4EBA\u5DE5\u667A\u80FD\u4E0D\u5149\u662F\u4E13\u4E1A\u8FD8\u662F\u4E00\u4E2A\u57FA\u672C\u7684\u7D20\u517B\uFF0C\u5B83\u662F\u4E00\u4E2A\u901A\u8BC6\u7684\u57FA\u672C\u7684\u7D20\u517B\u3002\u4E00\u65B9\u9762\u5462\uFF0C\u56E0\u4E3A\u4EBA\u5DE5\u667A\u80FD\u7684\u5E94\u7528\u975E\u5E38\u5E7F\u6CDB\uFF0C\u4F60\u4E86\u89E3\u5B83\u7684\u539F\u7406\uFF0C\u4F60\u5C31\u6709\u80FD\u529B\u66F4\u597D\u5730\u53BB\u7528\u3002\u5C31\u50CF\u8FD9\u79CD\u6C34\u3001\u7535\u4E00\u6837\uFF0C\u4F60\u4E0D\u5B66\u7269\u7406\uFF0C\u4E0D\u5B66\u6D41\u4F53\u529B\u5B66\uFF0C\u4F60\u53EF\u80FD\u5728\u7406\u89E3\u8FD9\u4E2A\u4E8B\u513F\u4E0A\u603B\u662F\u4F1A\u6B20\u5B8C\u5168\u662F\u9760\u7ECF\u9A8C\u3002\u7B2C\u4E8C\u4E2A\uFF0C\u5B83\u4E5F\u4EE3\u8868\u7740\u672A\u6765\u6570\u5341\u5E74\u7684\u4E00\u4E2A\u53D1\u5C55\u8D8B\u52BF\u3002"
  },
  {
    "time": 945,
    "speaker": "\u6559\u5E08",
    "text": "\u5B83\u4F1A\u5F71\u54CD\u672A\u6765\u6570\u5341\u5E74\u5C06\u957F\u671F\u5F71\u54CD\u6211\u4EEC\u7684\u5B66\u4E60\u548C\u804C\u4E1A\u53D1\u5C55\u3002\u90A3\u8FD9\u4E2A\u5BF9\u6211\u4EEC\u7684\u4E8B\u4E1A\u7684\u5E2E\u52A9\uFF0C\u5BF9\u4E2A\u4EBA\u53D1\u5C55\u4F1A\u6709\u5F88\u5927\u5E2E\u52A9\u3002\u5B83\u662F\u7B2C\u56DB\u6B21\u8FD9\u79CD\u4EA7\u4E1A\u9769\u547D\u7684\u4E00\u4E2A\u6838\u5FC3\u9A71\u52A8\u529B\uFF0C\u4EBA\u5DE5\u667A\u80FD\u662F\u957F\u671F\u7684\u4E00\u4E2A\u79D1\u7814\u65B9\u5411\u3002\u4E5F\u5C31\u662F\u8BF4\uFF0C\u8FD9\u4E2A\u4E00\u76F4\u6CA1\u6709\u7814\u7A76\uFF0C\u7279\u522B\u8FD8\u6709\u5F88\u591A\u4E0D\u5728\u4E8E\u5B83\u662F\u4E00\u4E2A\u8BA1\u7B97\u673A\u95EE\u9898\uFF0C\u800C\u5728\u4E8E\u5B83\u662F\u4EBA\u7C7B\u667A\u80FD\u7684\u4E00\u4E2A\u6A21\u62DF\uFF0C\u8FD9\u662F\u6BD4\u8F83\u96BE\u3002"
  },
  {
    "time": 980,
    "speaker": "\u6559\u5E08",
    "text": "\u8FD9\u4E5F\u662F\u6211\u4EEC\u9700\u8981\u4E0D\u65AD\u62D3\u5C55\u81EA\u8EAB\u80FD\u529B\u7684\u539F\u56E0\u3002\u90A3\u4E48\u4EBA\u7C7B\u7684\u9700\u6C42\uFF0C\u73B0\u5728\u53EF\u80FD\u4FE1\u606F\u4E16\u754C\u3001\u6570\u636E\u4E16\u754C\u5927\u5BB6\u3002\u4F46\u662F\u57FA\u4E8E\u4EBA\u5DE5\u667A\u80FD\u7684\u77E5\u8BC6\u4E16\u754C\u548C\u601D\u60F3\u3002\u8FD9\u662F\u6211\u4EEC\u53BB\u4E86\u6211\u4EEC\u6700\u540E\u4EBA\uFF0C\u4EBA\u5E94\u66F4\u591A\u5730\u6295\u5165\u77E5\u8BC6\u4E0E\u601D\u60F3\u7684\u521B\u9020\uFF0C\u628A\u4FE1\u606F\u4E0E\u6570\u636E\u5904\u7406\u4EA4\u7ED9\u8BA1\u7B97\u673A\u3002\u540C\u65F6\u4EBA\u5DE5\u667A\u80FD\u73B0\u5728\u53D1\u5C55\u7684\u867D\u7136\u5FEB\uFF0C\u4F46\u5B9E\u9645\u4E0A\u8FD8\u6709\u5F88\u591A\u95EE\u9898\uFF0C\u5F88\u591A\u5F88\u591A\u3002"
  },
  {
    "time": 1017,
    "speaker": "\u6559\u5E08",
    "text": "\u4F60\u4EEC\u53EF\u4EE5\u5728\u91CC\u8FB9\u5EFA\u529F\u7ACB\u4E1A\u3002\u90A3\u4E48\u4EBA\u5DE5\u667A\u80FD\u5728\u73B0\u5728\u8FD9\u4E2A\u573A\u666F\u4E0B\u9762\u8FDB\u884C\u5B66\u4E60\uFF0C\u5B83\u6709\u5F88\u591A\u5B9E\u7528\u7684\u4EF7\u503C\u3002\u8FD9\u662F\u6211\u4EEC\u91CD\u70B9\u5173\u6CE8\u7684\uFF0C\u5C31\u662F\u8FD9\u79CD\u8D4B\u80FD\u4F5C\u7528\u3002\u4E00\u79CD\u662F\u5728\u667A\u80FD\u60C5\u51B5\u4E0B\uFF0C\u4E5F\u5C31\u662F\u667A\u80FD\u65E0\u5904\u4E0D\u5728\u3002\u6709\u4E24\u65B9\u9762\uFF0C\u4E00\u65B9\u9762\u662F\u57FA\u7840\u8BBE\u65BD\u3002"
  },
  {
    "time": 1050,
    "speaker": "\u6559\u5E08",
    "text": "\u4E5F\u8BB8\u6211\u4EEC\u73B0\u5728\u8FD8\u6CA1\u6709\u771F\u6B63\u8FBE\u5230\u5B8C\u5168\u7684\u65E0\u5904\u4E0D\u5728\u3002\u4F46\u662F\u5927\u5BB6\u53EF\u4EE5\u60F3\u8C61\uFF0C\u53EA\u8981\u6211\u4EEC\u7684\u82AF\u7247\u8DB3\u591F\u4FBF\u5B9C\uFF0C\u7535\u6C60\u4F9B\u7535\u6BD4\u8F83\u597D\u3002\u90A3\u5927\u5BB6\u5750\u7684\u6905\u5B50\u3001\u7528\u7684\u684C\u5B50\uFF0C\u751A\u81F3\u662F\u4F60\u7684\u9910\u76D8\u91CC\u3002\u5B8C\u5168\u90FD\u53EF\u4EE5\u642D\u8F7D\u4EBA\u5DE5\u667A\u80FD\u3002\u8FD9\u6837\u4F60\u5750\u5728\u6905\u5B50\u4E0A\uFF0C\u6765\u4E86\u4E4B\u540E\u8FDB\u884C\u5FEB\u9012\u5730\u5740\u8F93\u5165\u3002\u5C31\u5B8C\u5168\u6309\u7167\u9884\u8BBE\u5730\u5740\u8FD9\u4E2A\u5730\u65B9\u6765\u81EA\u52A8\u586B\u5165\uFF0C\u8FD9\u662F\u4E00\u79CD\u5F88\u597D\u7684\u673A\u5236\u3002"
  },
  {
    "time": 1080,
    "speaker": "\u6559\u5E08",
    "text": "\u90A3\u4E48\u53E6\u5916\u4E00\u4E2A\u5E7F\u6CDB\u5E94\u7528\u662F\u591A\u573A\u666F\u3001\u591A\u7528\u6237\u3002\u4E5F\u5C31\u662F\u5927\u5BB6\u7684\u5404\u79CD\u5404\u6837\u7684\u4E13\u4E1A\u9886\u57DF\u3001\u751F\u6D3B\u9886\u57DF\u3002\u4E0D\u540C\u7684\u4EBA\u90FD\u53EF\u4EE5\u4ECE\u4E2D\u53D7\u76CA\u3002\u6240\u4EE5\u8FD9\u4E24\u4E2A\u5E7F\u6CDB\u5E94\u7528\u662F\u4EBA\u5DE5\u667A\u80FD\u5B66\u4E60\u7684\u4E00\u4E2A\u5F88\u91CD\u8981\u7684\u65B9\u9762\u3002\u597D\uFF0C\u6211\u4EEC\u4E86\u89E3\u4E86\u4E3A\u4EC0\u4E48\u8981\u5B66\u4E60\u4EBA\u5DE5\u667A\u80FD\u3002\u90A3\u6211\u4EEC\u5C31\u770B\u4E00\u770B\u4EBA\u5DE5\u667A\u80FD\u4E00\u8DEF\u8D70\u6765\uFF0C\u80FD\u4ECE\u4E2D\u603B\u7ED3\u51FA\u4EC0\u4E48\u3002\u90A3\u6211\u5FEB\u901F\u5730\u628A\u4EBA\u5DE5\u667A\u80FD\u7684\u5386\u53F2\u7ED9\u5927\u5BB6\u7B80\u5355\u8BF4\u4E00\u4E0B\u3002"
  },
  {
    "time": 1114,
    "speaker": "\u6559\u5E08",
    "text": "\u5927\u6982\u4ECE1950\u5E74\u56FE\u7075\u5F00\u59CB\u63D0\u51FA\u8FD9\u4E2A\u6982\u5FF5\u3002\u7136\u540E\u4E4B\u540E1956\u5E74\u8FBE\u7279\u8305\u65AF\u4F1A\u8BAE\uFF0C\u9A6C\u6587\xB7\u660E\u65AF\u57FA\u8FD8\u6709\u7EA6\u7FF0\xB7\u9EA6\u5361\u897F\u3002\u4ED6\u4EEC\u4E00\u8D77\u5728\u8FBE\u7279\u8305\u65AF\u8FD9\u4E2A\u89C4\u6A21\u4E0D\u5927\u7684\u5B66\u9662\u3002\u7136\u540E\u63D0\u51FA\u4E86\u4EBA\u5DE5\u667A\u80FD\u7684\u6982\u5FF5artificialintelligence\u3002\u6240\u4EE5\u5230\u73B0\u572870\u5E74\u4E4B\u540E\uFF0C\u5B83\u4E00\u5171\u7ECF\u5386\u4E86\u4E09\u8D77\u4E24\u843D\u3002\u6240\u4EE5\u5F53\u8C08\u5230\u4EBA\u5DE5\u667A\u80FD\u7684\u5386\u53F2\u65F6\uFF0C\u6211\u4EEC\u8981\u77E5\u9053\u4E09\u8D77\u4E24\u843D\u3002\u5F53\u7136\u4E09\u8D77\u4E24\u843D\u80CC\u540E\uFF0C\u6211\u4EEC\u80AF\u5B9A\u66F4\u5173\u5FC3\u7684\u662F\u843D\u7684\u539F\u56E0\u548C\u8D77\u7684\u539F\u56E0\u3002"
  },
  {
    "time": 1149,
    "speaker": "\u6559\u5E08",
    "text": "\u7136\u540E\u4ECE\u4E2D\u5438\u53D6\u6559\u8BAD\uFF0C\u5426\u5219\u4F60\u597D\u4E0D\u5BB9\u6613\u5B66\u4E60\u4E86\u3002\u9009\u62E9\u7528\u4EBA\u5DE5\u667A\u80FD\u5BF9\u533B\u7597\u8FDB\u884C\u8D4B\u80FD\u3002\u7ED3\u679C\u4F60\u4E00\u4E0D\u5C0F\u5FC3\u8DCC\u5165\u8C37\u5E95\uFF0C\u5BF9\u4F60\u7684\u4E8B\u4E1A\u53D1\u5C55\u548C\u65F6\u95F4\u90FD\u662F\u5F88\u5927\u7684\u635F\u5931\u3002\u90A3\u4E48\u7B2C\u4E00\u6B21\u7684\u7E41\u8363\u91CC\u6709\u5F88\u591A\u7ECF\u5178\u7684\u4E8B\u60C5\u3002\u6BD4\u5982\u8BF4\u903B\u8F91\u7406\u8BBA\u5BB6\u3002\u7F57\u68EE\u5E03\u62C9\u7279\u63D0\u51FA\u6765\u7684\u795E\u7ECF\u7F51\u7EDC\u611F\u77E5\u673A\u3002\u5B83\u5728\u90A3\u4E2A\u65F6\u5019\u5C31\u8BF4\u53EF\u4EE5\u8BC6\u522B26\u4E2A\u5B57\u6BCD\u7684\u5149\u5B66\u7279\u5F81\u3002"
  },
  {
    "time": 1183,
    "speaker": "\u6559\u5E08",
    "text": "\u8FD8\u6709\u8BED\u4E49\u7F51\u7EDC\u7684\u63D0\u51FA\u7C7B\u4F3C\u4E8E\u6211\u4EEC\u73B0\u5728\u7684\u77E5\u8BC6\u7F51\u7EDC\u3002\u8FD8\u6709ELIZA\u4E5F\u662F\u4E00\u4E2A\u65E9\u671F\u7684\u81EA\u7136\u8BED\u8A00\u5BF9\u8BDD\u7CFB\u7EDF\u3002\u6240\u4EE5\u5F53\u65F6ELIZA\u63D0\u51FA\u6765\u7684\u65F6\u5019\uFF0C\u8FD8\u6709\u5F88\u591A\u4EBA\u89C9\u5F97\u5F88\u597D\u5947\u3002\u89C9\u5F97\u975E\u5E38\u6709\u667A\u80FD\u3002\u4F46\u5176\u5B9E\u5B83\u80CC\u540E\u6709\u4E00\u4E2A\u5F88\u7B80\u5355\u7684\u6280\u5DE7\uFF0C\u5B83\u7684\u5BF9\u8BDD\u5927\u6982\u662F\u8FD9\u6837\u5B50\u7684\u3002\u6BD4\u5982\u8BF4\u6211\u73B0\u5728\u5F88\u96BE\u53D7\uFF0C\u5B83\u7684\u56DE\u7B54\u53EF\u80FD\u662F\u8BF4\u6211\u4E5F\u5F88\u4F24\u5FC3\u3002\u5443\uFF0C\u4ECA\u5929\u5929\u6C14\u600E\u4E48\u6837\uFF1F\u7136\u540E\u4F60\u89C9\u5F97\u5462\uFF0C\u6216\u8005\u662F\u4F60\u5728\u8BF4\u67D0\u4E00\u4EF6\u4E8B\u7684\u65F6\u5019\u3002"
  },
  {
    "time": 1215,
    "speaker": "\u6559\u5E08",
    "text": "\u5B83\u4F1A\u628A\u4F60\u7684\u8BED\u5E8F\u7A0D\u5FAE\u8C03\u6574\u4E00\u4E0B\u6765\u95EE\u4F60\uFF0C\u6240\u4EE5\u5B83\u4E00\u76F4\u662F\u4E00\u4E2A\u503E\u542C\u8005\u3002\u6240\u4EE5\u5982\u679C\u6211\u4EEC\u60F3\u6210\u4E3A\u4E00\u4E2A\u5F88\u597D\u7684\u4E3B\u6301\u4EBA\u53BB\u503E\u542C\u7684\u8BDD\u3002\u5176\u5B9E\u4F60\u53EA\u9700\u8981\u63A5\u7740\u8C08\u8BDD\u4EBA\u7684\u8BDD\u7B80\u5355\u8BF4\u4E00\u8BF4\u3002\u8868\u793A\u4E00\u4E9B\u8BA4\u540C\u6216\u8005\u63D0\u4E00\u4E9B\u95EE\u9898\uFF0C\u4E3A\u4EC0\u4E48\u5462\uFF1F\u662F\u4EC0\u4E48\u5462\uFF1F\u5B83\u7528\u8FD9\u79CD\u65B9\u5F0F\u5C31\u8BA9\u4EBA\u611F\u89C9\u7684\u786E\u6709\u4EBA\u7684\u7279\u70B9\u5728\u91CC\u9762\u3002\u90A3\u662F\u65E9\u671F\u7684\u81EA\u7136\u8BED\u8A00\u5904\u7406\u3002\u5728\u8FD9\u7B2C\u4E00\u6B21\u7E41\u8363\u4E4B\u540E\uFF0C\u5927\u5BB6\u770B\u91CC\u9762\u6709\u795E\u7ECF\u7F51\u7EDC\u88AB\u63D0\u51FA\u3002"
  },
  {
    "time": 1249,
    "speaker": "\u6559\u5E08",
    "text": "\u7136\u540E\u80FD\u591F\u8BC6\u522B\u5F71\u50CF\u3001\u8BED\u4E49\uFF0C\u4E5F\u5C31\u662F\u77E5\u8BC6\uFF0C\u8FD8\u6709\u5BF9\u8BDD\u3002\u8FD9\u662F\u4E0D\u662F\u8BA9\u6574\u4E2A\u793E\u4F1A\u89C9\u5F97\u975E\u5E38\u5174\u594B\uFF0C\u53EF\u4EE5\u8BA9\u8BA1\u7B97\u673A\u53BB\u5B66\u4E60\u77E5\u8BC6\u3002\u8BA9\u8BA1\u7B97\u673A\u53BB\u63A8\u6F14\u4E1C\u897F\uFF0C\u7136\u540E\u8FD8\u80FD\u5B8C\u6210\u5BF9\u8BDD\u3002\u90A3\u5F88\u591A\u4E1C\u897F\u90FD\u53EF\u4EE5\u5411\u8BA1\u7B97\u673A\u54A8\u8BE2\uFF0C\u8FD9\u4E00\u4E0B\u5B50\u5927\u5BB6\u7684\u9884\u671F\u5C31\u63D0\u9AD8\u4E86\u3002\u7136\u540E\u5F88\u4E0D\u5E78\u5C31\u8FDB\u5165\u4E86\u4E00\u4E2A\u51AC\u5929\uFF0C\u51AC\u5929\u7684\u539F\u56E0\u3002\u8FD9\u4E24\u6B21\u51AC\u5929\u7684\u539F\u56E0\u90FD\u662F\u9884\u671F\u8FC7\u9AD8\u540E\u8DCC\u843D\u3002"
  },
  {
    "time": 1280,
    "speaker": "\u6559\u5E08",
    "text": "\u6240\u4EE5\u56DE\u5230\u73B0\u5728\uFF0C\u6211\u4EEC\u4E5F\u8981\u9632\u6B62\u9884\u671F\u8FC7\u9AD8\u3002\u8FD9\u6B21\u51AC\u5929\u7684\u4E00\u4E2A\u539F\u56E0\u662F\u7B97\u529B\u6709\u9650\u3002\u6BD4\u5982\u8BF4\u505A\u89C6\u89C9\u8BC6\u522B\uFF0C\u6211\u4EEC\u4EBA\u7684\u773C\u775B\u8FDB\u884C\u8BC6\u522B\u3002\u90A3\u8BA1\u7B97\u91CF\u975E\u5E38\u5927\u3002\u4F46\u662F\u5BF9\u4E8E\u6211\u4EEC\u6765\u8BF4\u662F\u6A21\u62DF\u6570\u5B57\u7535\u8DEF\u548C\u6A21\u62DF\u7535\u8DEF\uFF0C\u6211\u4EEC\u662F\u6A21\u62DF\u7684\u3002\u800C\u8BA9\u8BA1\u7B97\u673A\u8BA1\u7B97\uFF0C\u5B83\u6574\u4E2A\u8FD0\u7B97\u91CF\u8D85\u8FC7\u4E86\u5F53\u65F6\u6700\u5927\u82AF\u7247\u7684\u80FD\u529B\u3002\u6700\u5F3A\u7684\u82AF\u7247\u53EA\u505A\u4E00\u4E2A\u5B57\u6BCD\u8BC6\u522B\u7684\u4E8B\u513F\uFF0C\u5B83\u90FD\u8FD0\u7B97\u4E0D\u597D\u3002"
  },
  {
    "time": 1311,
    "speaker": "\u6559\u5E08",
    "text": "\u8981\u8BC6\u522B\u5F88\u591A\u56FE\u50CF\u3002\u53E6\u5916\u5C31\u662F\u8981\u5B58\u50A8\u5927\u91CF\u7684\u6570\u636E\uFF0C\u6BD4\u5982\u8BF4\u505A\u4EBA\u8138\u8BC6\u522B\u3001\u505A\u673A\u5668\u7FFB\u8BD1\u3002\u5B58\u50A8\u6D77\u91CF\u7684\u6570\u636E\uFF0C\u8FD9\u96BE\u4EE5\u5B9E\u73B0\u3002\u90A3\u4E48\u8FD8\u6709\u7F51\u7EDC\u6709\u9650\uFF0C\u6574\u4E2A\u6C42\u89E3\u7A7A\u95F4\u662F\u7206\u70B8\u7684\u3002\u5B83\u80FD\u8868\u8FBE\u7684\u7F51\u7EDC\u4E0D\u662F\u6211\u4EEC\u4F20\u8F93\u6570\u636E\u8868\u793A\u7684\u65B9\u7A0B\u7684\u53C2\u6570\u3002\u6709\u7EC4\u5408\u7206\u70B8\u7684\u95EE\u9898\u3002\u6240\u4EE5\u5927\u5BB6\u89C9\u5F97\u8FD9\u4E8B\u513F\u8DDF\u4EBA\u6BD4\u8D77\u6765\u5C31\u662F\u5C0F\u513F\u79D1\uFF0C\u7136\u540E\u4E00\u4E0B\u5B50\u8FDB\u5165\u5230\u3002"
  },
  {
    "time": 1350,
    "speaker": "\u6559\u5E08",
    "text": "\u7B2C\u4E8C\u6B21\u7E41\u8363\u5927\u6982\u662F\u572880\u5E74\u4EE3\u523090\u5E74\u4EE3\u8FD9\u4E2A\u8FC7\u7A0B\u3002\u7136\u540E\u6211\u4EEC\u4E0A\u8282\u8BFE\u8BB2\u4E86\u4E13\u5BB6\u7CFB\u7EDF\uFF0C\u5C31\u662F\u5728\u90A3\u4E2A\u65F6\u5019\u3002\u8FD8\u6709\u65E5\u672C\u7684\u7B2C\u4E94\u4EE3\u8BA1\u7B97\u673A\u9879\u76EE\u3002\u5F53\u65F6\u4ED6\u4EEC\u53F7\u79F0\u752810\u523020\u5E74\uFF0C\u5B9E\u73B0\u8DDF\u4EBA\u80FD\u5BF9\u8BDD\u7684\u7ED3\u679C\u3002\u8FD9\u4E9B\u90FD\u662F\u9884\u671F\u5931\u8D25\uFF0C\u9884\u671F\u843D\u7A7A\u3002\u6240\u4EE5\u53C8\u8FC5\u901F\u8FDB\u5165\u5230\u4E86\u4EBA\u5DE5\u667A\u80FD\u7684\u7B2C\u4E8C\u4E2A\u9636\u6BB5\uFF0C\u4E13\u5BB6\u7CFB\u7EDF\u7684\u95EE\u9898\u3002"
  },
  {
    "time": 1381,
    "speaker": "\u6559\u5E08",
    "text": "\u5B83\u66F4\u65B0\u5F88\u56F0\u96BE\uFF0C\u89C4\u5219\u4E0D\u65AD\u63D0\u51FA\u3002\u4F46\u662F\u6574\u4E2A\u4E16\u754C\u7684\u89C4\u5219\u6709\u591A\u5C11\u4E2A\u5462\uFF1F\u4F60\u63D0\u4E0D\u51FA\uFF0C\u540C\u65F6\u89C4\u5219\u4E0E\u89C4\u5219\u4EA4\u7EC7\u5728\u4E00\u8D77\uFF0C\u600E\u4E48\u89E3\u51B3\u51B2\u7A81\u95EE\u9898\u5462\uFF1F\u4E5F\u662F\u4E00\u4E2A\u5F88\u5927\u7684\u95EE\u9898\uFF0C\u7B2C\u4E8C\u4E2A\u75DB\u70B9\u5C31\u662F\u4E13\u5BB6\u7CFB\u7EDF\u4E0D\u80FD\u81EA\u4E3B\u5B66\u4E60\u3002\u8FD8\u5F97\u4EBA\u53BB\u6784\u5EFA\u3002\u4F46\u662F\u5DF2\u7ECF\u63D0\u4E86\u4E00\u4E07\u6761\u4E86\uFF0C\u7136\u540E\u518D\u63D0\u4E00\u4E07\u96F6\u4E00\u6761\u89C4\u5219\u3002\u90A3\u662F\u4E0D\u662F\u6211\u8981\u770B\u5230\u524D\u4E00\u4E07\u6761\uFF0C\u90A3\u8FD9\u4E2A\u4E8B\u5B83\u53C8\u4E0D\u80FD\u81EA\u4E3B\u5B66\u4E60"
  },
  {
    "time": 1411,
    "speaker": "\u6559\u5E08",
    "text": "\u8BA9\u4E13\u5BB6\u53BB\u5E72\u8FD9\u4E2A\u4E8B\u513F\u4E13\u5BB6\u53D7\u4E0D\u4E86\uFF0C\u4EBA\u53D7\u4E0D\u4E86\uFF0C\u673A\u5668\u5B66\u4E60\u7684\u7B97\u6CD5\u53D1\u5C55\u7F13\u6162\u8FD8\u6709\u5C31\u662F\u4EBA\u5DE5\u667A\u80FD\u7814\u7A76\u7684\u8D44\u91D1\u51CF\u5C11\u4E5F\u662F\u56E0\u4E3A\u90A3\u65F6\u5019\u82F9\u679C\u5F00\u59CB\u751F\u4EA7\u4E2A\u4EBA\u7535\u8111\u4E00\u4E0B\u5B50\u662F\u539F\u6765\u505A\u4E13\u95E8\u79D1\u5B66\u8BA1\u7B97\u7684\u8BA1\u7B97\u673A\u5382\u5546\u4F46\u662F\u82F9\u679C\u7535\u8111\u53C8\u4E0D\u80FD\u4E00\u4E0B\u5B50\u8FDB\u884C\u590D\u6742\u7684\u8FD0\u7B97\u539F\u6765\u5927\u5BB6\u662F\u901A\u8FC7\u5356\u786C\u4EF6\u6765\u8D5A\u4EBA\u5DE5\u667A\u80FD\u6574\u4E2A\u884C\u4E1A\u7684\u94B1"
  },
  {
    "time": 1443,
    "speaker": "\u6559\u5E08",
    "text": "\u8FD9\u6837\u7684\u4E00\u4E2A\u5546\u4E1A\u6A21\u5F0F\u4E0D\u5B58\u5728\u4E86\uFF0C\u8D44\u91D1\u5C31\u79BB\u5F00\u4E86\u7B2C\u4E09\u6B21\uFF0C\u7B2C\u4E09\u6B21\u8FD9\u4E2A\u5185\u5BB9\u5C31\u6BD4\u8F83\u591A\u4E86\uFF0C\u6211\u5217\u5F97\u6BD4\u8F83\u5168\u90A3\u4E48\u9996\u5148\u4ECE1997\u5E74\u5F00\u59CB\uFF0C\u4ECE\u8C37\u5E95\u5F80\u4E0A\u5347\uFF0C\u6211\u4EEC\u7ECF\u5E38\u4F1A\u6709\u4E00\u4E9B\u91CD\u8981\u7684\u4E8B\u60C5\u50CF\u963F\u5C14\u6CD5\u72D7\uFF0C\u50CFGT\u90A31997\u5E74\uFF0C\u5728\u5927\u5BB6\u51FA\u751F\u4E4B\u524D\uFF0C\u5B83\u5C31\u6253\u8D25\u4E86\u5361\u65AF\u5E15\u7F57\u592B\u4ED6\u4E5F\u662F\u8FDE\u7EED17\u5E74\u7684\u56FD\u9645\u8C61\u68CB\u51A0\u519B\uFF0C\u57FA\u672C\u4E0A\u5C31\u662F\u4E00\u4E2A\u65F6\u4EE3\u6027\u7684\u4EBA\u7269\u4F46\u662F\u88ABIBM\u7684\u4E00\u4E2A\u53EB\u6DF1\u84DD\u7684\u7CFB\u7EDF\u7ED9\u6253\u8D25\u4E86"
  },
  {
    "time": 1477,
    "speaker": "\u6559\u5E08",
    "text": "\u6240\u4EE5\u4E00\u4E0B\u5B50\u5927\u5BB6\u53C8\u89C9\u5F97\u4EBA\u5DE5\u667A\u80FD\u884C\u5426\u5219\u4E3A\u4EC0\u4E48\u80FD\u6253\u8D25\u6211\u4EEC\u6700\u725B\u7684\u6700\u5F3A\u5927\u8111\u5462\uFF1F\u5927\u5BB6\u4F1A\u597D\u5947\uFF0C\u7136\u540E\u5462\uFF0C\u57282006\u5E74\u6211\u4EEC\u73B0\u5728\u4E00\u76F4\u5728\u7528\u7684\u6DF1\u5EA6\u5B66\u4E60\u52A0\u62FF\u5927\u79D1\u5B66\u5BB6\u6770\u5F17\u91CC\xB7\u8F9B\u987F\u53D1\u8868\u4E86\u4E00\u7BC7\u6587\u7AE0\u7136\u540E\u4E4B\u540E2011\u5E74\uFF0C\u6C83\u68EE\uFF0C\u5C31\u662F\u6211\u4EEC\u4E0A\u8282\u8BFE\u8BB2\u7684\u90A3\u4E2A\u90A3\u4E48\u5B83\u5728\u300A\u5371\u9669\u8FB9\u7F18\u300B\u8FD9\u4E2A\u8282\u76EE\u91CC\u8FB9\uFF0C\u9996\u5148\u6765\u770B"
  },
  {
    "time": 1507,
    "speaker": "\u6559\u5E08",
    "text": "\u8FD9\u662F\u5728\u4E13\u4E1A\u9886\u57DF\uFF0C\u4E0B\u8C61\u68CB\u68CB\u76D8\u6709\u9650\uFF0C\u641C\u7D22\u7A7A\u95F4\u6709\u9650\u4F46\u662F\u5728\u81EA\u7136\u8BED\u8A00\u7684\u95EE\u7B54\u65B9\u9762\uFF0C\u8FD9\u53C8\u662F\u4E00\u4E2A\u5168\u79D1\u77E5\u8BC6\u3001\u767E\u79D1\u77E5\u8BC6\uFF0C\u5B83\u80FD\u83B7\u80DC\u540C\u65F6\u5462\uFF0CAppleSIRI\u5230GoogleNow\uFF0C\u6211\u4EEC\u73B0\u5728\u5F88\u591A\u4EBA\u90FD\u5728\u7528\u7740\u5404\u79CD\u5404\u6837\u7684\u8BED\u97F3\u52A9\u624B\u4F46\u5B83\u521A\u63D0\u51FA\u6765\u7684\u65F6\u5019\u8FD8\u662F\u975E\u5E38\u65B0\u9896\uFF0C\u7136\u540E\u518D\u52302014\u5E74\u7684\u65F6\u5019\u5C31\u53EF\u4EE5\u4ECE\u89C6\u9891\u91CC\u8FB9\u8BC6\u522B\u51FA\u732B\u6765\u4E86\uFF0C\u90A3\u8BC6\u522B\u51FA\u732B\u610F\u5473\u7740\u4EC0\u4E48\uFF1F\u610F\u5473\u7740\u6211\u7684\u89C6\u9891\u5C31\u662F\u56FE\u50CF\u8D44\u6599\u3001\u89C6\u9891\u6D41\u8D44\u6599\u53EF\u4EE5\u68C0\u7D22"
  },
  {
    "time": 1542,
    "speaker": "\u6559\u5E08",
    "text": "\u6211\u53EF\u4EE5\u641C\u7D22\u4E00\u4E2A\u4EBA\u540D\uFF0C\u7136\u540E\u628A\u89C6\u9891\u91CC\u8FB9\u6709\u8FD9\u4E2A\u4EBA\u540D\u7684\u65F6\u95F4\u65F6\u95F4\u5757\u6211\u5168\u7ED9\u62FF\u51FA\u6765\u7136\u540E\u52302016\u5E74\u7684\u65F6\u5019\u963F\u5C14\u6CD5\u72D7\u6253\u8D25\u4E86\u674E\u4E16\u77F3\uFF0C\u89C9\u5F97\u4E0B\u8C61\u68CB\u7684\u7A7A\u95F4\u592A\u6709\u9650\u5927\u5BB6\u4F1A\u6709\u4E00\u4E2A\u9119\u89C6\u94FE\u4F46\u662F\u5F53\u56F4\u68CB\u4E5F\u88AB\u8BA1\u7B97\u673A\u7EDF\u6CBB\u4E86\u5927\u5BB6\u5C31\u89C9\u5F97\u4EBA\u7C7B\u6700\u540E\u4E00\u4E2A\u667A\u529B\u9AD8\u5CF0\u53C8\u88AB\u8FD9\u4E2A\u673A\u5668\u7ED9\u5360\u4E86\u7136\u540E\u4E4B\u540E\u518D\u52302022\u5E7411\u6708\u4EFD\uFF0COpenAI\u53D1\u5E03\u4E86ChatGPT"
  },
  {
    "time": 1573,
    "speaker": "\u6559\u5E08",
    "text": "\u4E00\u76F4\u5230\u73B0\u5728\uFF0CGPT4\u7B49\u5404\u79CD\u5404\u6837\u7684\u5927\u6A21\u578B\u90FD\u5728\u53D1\u5E03\u5728\u7B2C\u4E09\u6B21\u8FD9\u6837\u7684\u4E00\u4E2A\u53D1\u751F\u7684\u8FC7\u7A0B\u4E2D\u91CC\u8FB9\u6838\u5FC3\u7684\u6DF1\u5EA6\u5B66\u4E60\u7B97\u6CD5\u5DF2\u7ECF\u53D8\u6210\u4E86\u5927\u7F51\u7EDC\u7136\u540E\u6570\u636E\u5462\uFF0C\u662F\u6D77\u91CF\u5B58\u50A8\u7684\u6570\u636E\u3001\u5927\u7B97\u529B\u6211\u4EEC\u7528GPU\u5584\u4E8E\u505A\u6D6E\u70B9\u8BA1\u7B97\u3001\u56FE\u50CF\u8BA1\u7B97\uFF0C\u7136\u540E\u6765\u505A\u8FD9\u4E2A\u6570\u5B66\u8BA1\u7B97\u8FD8\u9700\u8981\u9AD8\u5E26\u5BBD\uFF0C\u8FD9\u4E9B\u90FD\u9700\u8981\u662F\u6D77\u91CF\u7684\u8D44\u6E90\u6240\u4EE5\u6211\u4EEC\u73B0\u5728\u5728\u7528\u8BA1\u7B97\u673A\u3001\u7528\u8FD9\u4E2A\u5927\u6A21\u578B\u7684\u65F6\u5019"
  },
  {
    "time": 1606,
    "speaker": "\u6559\u5E08",
    "text": "\u5F88\u591A\u65F6\u5019\u95EE\u9898\u5728\u4E8E\u80FD\u6E90\u5371\u673A\u5BF9\u80FD\u6E90\u7684\u51B2\u51FB\u5F88\u5927\u6240\u4EE5\u5728\u8FD9\u4E2A\u8FC7\u7A0B\u4E2D\uFF0C\u5927\u5BB6\u8FD8\u662F\u80FD\u770B\u5230\u6211\u4EEC\u73B0\u5728\u5904\u4E8E\u7B2C\u4E09\u4EE3\u65F6\u671F\u63A5\u7740\u56DE\u843D\uFF0C\u5728\u62C5\u5FC3\u7740\u90A3\u4E48\u5728\u8FD9\u4E2A\u8FC7\u7A0B\u4E2D\uFF0C\u6211\u4EEC\u80FD\u770B\u5230\u6838\u5FC3\u7684\u6280\u672F\u3001\u6838\u5FC3\u7684\u601D\u8DEF\u6709\u4E24\u4E2A\u65B9\u9762\u5176\u5B9E\u5B66\u6D3E\u5F88\u591A\uFF0C\u6709\u4E94\u516D\u4E2A\u5B66\u6D3E\uFF0C\u4F46\u662F\u6838\u5FC3\u7684\u4E00\u4E2A\u662F\u77E5\u8BC6\uFF0C\u5C31\u662F\u7B26\u53F7\u4E00\u4E2A\u662F\u8FDE\u63A5\u4E3B\u4E49\uFF0C\u5373\u6570\u636E\u9A71\u52A8\uFF0C\u4E3A\u4EC0\u4E48\u6709\u8FD9\u6837\u7684\u4E1C\u897F\uFF0C\u5B83\u672C\u8D28\u5728\u505A\u4EC0\u4E48\uFF1F"
  },
  {
    "time": 1643,
    "speaker": "\u6559\u5E08",
    "text": "\u672C\u8D28\u4E0A\u90FD\u5728\u505A\u77E5\u8BC6\u8868\u8FBE\uFF0C\u672C\u8D28\u4E0A\u90FD\u5728\u505A\u77E5\u8BC6\u8868\u8FBE\u5F53\u4F60\u60F3\u8868\u8FBE\u4E00\u4E2A\u77E5\u8BC6\u7684\u65F6\u5019\u4F60\u5230\u5E95\u662F\u7528\u4EBA\u7C7B\u7684\u8FD9\u79CD\u4E00\u6761\u4E00\u6761\u7684\u89C4\u5219\u6BD4\u5982\u8BF4\u56DB\u4E2A\u516C\u7406\u628A\u8FD9\u4E2A\u6570\u5B66\u7684\u57FA\u672C\u60C5\u51B5\u7ED9\u63CF\u8FF0\u51FA\u6765\u597D\uFF0C\u8FD9\u662F\u6211\u7528\u516C\u7406\uFF0C\u8FD8\u662F\u8BF4\u6211\u7528\u4E00\u5927\u5806\u7684\u8FD9\u4E9B\u6570\u5B66\u7684\u7ED3\u679C1+1=2\u8FD9\u6837\u7684\u6570\u5B66\u7B97\u5F0F\uFF0C\u7136\u540E\u6765\u63CF\u8FF0\u6570\u5B66\u4E16\u754C\u6240\u4EE5\u8FD9\u610F\u5473\u7740\u8868\u793A\u77E5\u8BC6\u6709\u77E5\u8BC6\u9A71\u52A8\u8FD9\u79CD\u65B9\u5F0F"
  },
  {
    "time": 1674,
    "speaker": "\u6559\u5E08",
    "text": "\u8FD8\u6709\u6570\u636E\u9A71\u52A8\u8FD9\u79CD\u65B9\u5F0F\u6211\u4EEC\u7528\u5927\u91CF\u7684\u6570\u636E\u53BB\u8BAD\u7EC3\u8BED\u97F3\u6211\u5E76\u4E0D\u544A\u8BC9\u5B83\u91CC\u8FB9\u8574\u542B\u7684\u89C4\u5F8B\u5C31\u50CF\u6211\u4EEC\u5C0F\u670B\u53CB\u5728\u4E09\u5C81\u4E4B\u524D\u3001\u4E0A\u5E7C\u513F\u56ED\u4E4B\u524D\uFF0C\u4F60\u57FA\u672C\u4E0A\u4E0D\u6559\u4ED6\u79D1\u5B66\u77E5\u8BC6\u4F46\u662F\u4ED6\u4E5F\u80FD\u77E5\u9053\u6254\u8D77\u6765\u7684\u4E1C\u897F\u4F1A\u843D\u5230\u5730\u4E0A\u4ED6\u4E5F\u4F1A\u77E5\u9053\u8FD9\u662F\u7238\u7238\uFF0C\u8FD9\u662F\u5988\u5988\uFF0C\u4E5F\u5728\u5B66\u7740\u8BA4\u8BC6\u4EBA\uFF0C\u5BF9\u5427\uFF1F\u6240\u4EE5\u6570\u636E\u4F9D\u7136\u662F\u8868\u793A\u77E5\u8BC6\u7684\u4E00\u79CD\u5F88\u597D\u7684\u65B9\u6CD5\u6211\u7528\u5927\u91CF\u7684\u6570\u636E\u53BB\u8868\u793A\u77E5\u8BC6\u4E00\u6837\u662F\u53EF\u4EE5\u8868\u8FBE\u7684"
  },
  {
    "time": 1708,
    "speaker": "\u6559\u5E08",
    "text": "\u8FD9\u4E24\u4E2A\u6D41\u6D3E\uFF0C\u77E5\u8BC6\u8868\u8FBE\u66F4\u7B80\u6D01\u4E00\u4E9B\uFF0C\u4F46\u662F\u89C4\u5219\u63D0\u5F97\u4E0D\u591F\u5168\u8FD9\u4E2A\u95EE\u9898\uFF0C\u6570\u636E\u8868\u8FBE\uFF0C\u5F53\u6211\u6709\u4E86\u5927\u6570\u636E\u7684\u65F6\u5019\u6211\u5C31\u53EF\u4EE5\u7528\u6570\u636E\u53BB\u8868\u8FBE\u4F46\u662F\u5904\u7406\u5927\u6570\u636E\u9700\u8981\u5927\u7B97\u529B\u3001\u5927\u7F51\u7EDC\u5F53\u7136\uFF0C\u5927\u6570\u636E\u3001\u5927\u7B97\u529B\u3001\u5927\u7F51\u7EDC\u3001\u9AD8\u5E26\u5BBD\u53C8\u5E26\u6765\u4E86\u80FD\u6E90\u7684\u5371\u673A\u5C31\u662F\u4F60\u73B0\u5728\u4F7F\u7528\u5927\u6A21\u578B\u770B\u8D77\u6765\u662F\u4EBA\u4EBA\u90FD\u5728\u4F7F\u7528\uFF0C\u5B9E\u9645\u4E0A\u662F\u6709\u4EBA\u5728\u80CC\u540E\u652F\u6491\uFF0C\u5BF9\u5427\uFF1F\u6240\u4EE5\u8FD9\u662F\u6211\u4EEC\u4ECE\u77E5\u8BC6\u9A71\u52A8\u5230\u6570\u636E\u9A71\u52A8"
  },
  {
    "time": 1742,
    "speaker": "\u6559\u5E08",
    "text": "\u90A3\u4E48\u5728\u6574\u4E2A\u8FD9\u4E2A\u4EA7\u4E1A\u7684\u89D2\u5EA6\u4E0A\u6211\u4EEC\u8FD8\u80FD\u770B\u5230\u7684\u5C31\u662F\u6700\u521D\u662F\u4EE5\u653F\u5E9C\u8D44\u52A9\u4E3A\u4E3B\u5230\u4E4B\u540E\u662F\u4EE5\u4EA7\u4E1A\u6295\u8D44\u4E3A\u4E3B\uFF0C\u653F\u5E9C\u8D44\u52A9\u4E3A\u8F85\u57FA\u672C\u4E0A\u5230\u4E86\u8FD9\u4E2A\u7B2C\u4E09\u6B21\u3001\u7B2C\u4E8C\u6B21\u7E41\u8363\u7B2C\u4E09\u6B21\u6CE2\u6298\u7684\u8FD9\u4E2A\u9636\u6BB5\u5168\u662F\u4EE5\u653F\u5E9C\u8D44\u52A9\u4E3A\u4E3B\uFF0C\u4E4B\u540E\u5462\uFF0C\u5C31\u4E0D\u80FD\u518D\u6295\u8D44\u4E86\u653F\u5E9C\u6295\u8D44\u4E00\u76F4\u662F\u4E8F\u635F\u7684\u653F\u5E9C\u6295\u8D44\u5B83\u4E0D\u662F\u8981\u6C42\u56DE\u62A5\uFF0C\u66F4\u591A\u7684\u662F\u8981\u6C42\u628A\u4E00\u4E2A\u4EA7\u4E1A\u632F\u5174\u8D77\u6765\u90A3\u4E48\u4EA7\u4E1A\u6295\u8D44\u80AF\u5B9A\u662F\u4EE5\u56DE\u62A5\u4E3A\u76EE\u7684"
  },
  {
    "time": 1774,
    "speaker": "\u6559\u5E08",
    "text": "\u540C\u6837\u5BF9\u4E8E\u6211\u4EEC\u667A\u6167\u533B\u7597\u8FD9\u4E00\u65B9\u5411\u7684\u4EA7\u4E1A\u6295\u8D44\u4E5F\u662F\u4E00\u4E2A\u7CFB\u7EDF\u5F53\u4F60\u505A\u4E00\u4E2A\u4E1C\u897F\uFF0C\u4F60\u9996\u5148\u8981\u95EE\u95EE\u533B\u9662\uFF0C\u95EE\u95EE\u8FD9\u4E9B\u533B\u7597\u5668\u68B0\u7684\u5382\u5546\u95EE\u95EE\u90A3\u4E9B\u517B\u8001\u670D\u52A1\u7684\u673A\u6784\uFF0C\u4ED6\u4EEC\u5BF9\u4F60\u8FD9\u4E2A\u611F\u4E0D\u611F\u5174\u8DA3\u613F\u4E0D\u613F\u4E3A\u6B64\u4ED8\u8D39\u6211\u4EEC\u4ECE\u91CC\u8FB9\u603B\u7ED3\u5230\u4E00\u4E2A\u89C4\u5F8B\uFF0C\u4E86\u89E3\u4E86\u4EBA\u5DE5\u667A\u80FD\u7684\u53D1\u5C55\u90A3\u6211\u4EEC\u8981\u56DE\u987E\u4E00\u4E0B\uFF0C\u7406\u6E05\u4EBA\u5DE5\u667A\u80FD\u7684\u6982\u5FF5"
  },
  {
    "time": 1807,
    "speaker": "\u6559\u5E08",
    "text": "\u963F\u5170\xB7\u56FE\u7075\uFF0C\u6211\u4EEC\u8BF4\u771F\u6B63\u610F\u4E49\u4E0A\u7684\u4EBA\u5DE5\u667A\u80FD\u4E0D\u662F\u8C01\u63D0\u4E86\u4EBA\u5DE5\u667A\u80FD\u8FD9\u4E2A\u8BCD\uFF0C\u8C01\u5C31\u662F\u4EBA\u5DE5\u667A\u80FD\u5148\u9A71\u8FD8\u662F\u770B\u4ED6\u7684\u8FD9\u79CD\u601D\u60F3\u4ED6\u5728\u8457\u540D\u7684\u4E00\u7BC7\u6587\u7AE0\u300A\u8BA1\u7B97\u673A\u5668\u4E0E\u667A\u80FD\u300B\u4E2D\uFF0C\u90A3\u65F6\u4ED6\u5E74\u9F84\u5F88\u8F7B\u56DB\u5341\u4E8C\u5C81\u5C31\u53BB\u4E16\u4E86\u4F46\u662F\u4ED6\u7684\u601D\u60F3\u975E\u5E38\u4E30\u5BCC\uFF0C\u6709\u56FE\u7075\u6D4B\u8BD5\u7B49\u7B49\u300A\u8BA1\u7B97\u673A\u5668\u4E0E\u667A\u80FD\u300B\u662F\u4ED6\u6700\u91CD\u8981\u7684\u4E00\u7BC7\u6587\u7AE0"
  },
  {
    "time": 1838,
    "speaker": "\u6559\u5E08",
    "text": "\u5728\u4ED6\u8FD9\u7BC7\u6587\u7AE0\u7684\u7ED3\u5C3E\u5904\u4ED6\u8BF4\u6211\u4EEC\u5E0C\u671B\u673A\u5668\u6700\u7EC8\u5728\u6240\u6709\u7EAF\u667A\u529B\u9886\u57DF\u4E0E\u4EBA\u7C7B\u7ADE\u4E89\u3002\u6700\u597D\u7684\u8D77\u70B9\u5728\u54EA\u91CC\uFF1F\u7814\u7A76\u8005\u63D0\u51FA\u95EE\u9898\uFF0C\u540E\u7EED\u7814\u7A76\u8005\u89E3\u51B3\u95EE\u9898\uFF0C\u4ED6\u662F\u4E00\u6D41\u5927\u725B\uFF0C\u5728\u63D0\u51FA\u95EE\u9898\u4ED6\u8BF4\u8981\u505A\u4EBA\u5DE5\u667A\u80FD\uFF0C\u5F53\u65F6\u4ED6\u6CA1\u63D0\u51FA\u8FD9\u4E2A\u8BCD\uFF0C\u201C\u4EBA\u5DE5\u667A\u80FD\u201D\u4E00\u8BCD\u57281956\u5E74\u63D0\u51FA\uFF1B\u56FE\u7075\u6D4B\u8BD5\u5219\u57281950\u5E74\u63D0\u51FA\uFF0C\u4ED6\u8BF4\u6700\u597D\u7684\u8D77\u70B9\u5728\u54EA\u4F60\u60F3\u53BB\u672A\u6765\uFF0C\u90A3\u6211\u4EEC\u73B0\u5728\u4ECE\u54EA\u513F\u8D77\u6B65\u5462"
  },
  {
    "time": 1869,
    "speaker": "\u6559\u5E08",
    "text": "\u6211\u4EEC\u7684\u7814\u7A76\u65B9\u5411\u662F\u4EC0\u4E48\u5462\u90A3\u4E48\u8FD9\u4E5F\u662F\u5F88\u56F0\u96BE\u7684\u8BB8\u591A\u4EBA\u8BA4\u4E3A\uFF0C\u62BD\u8C61\u7684\u6D3B\u52A8\u56FD\u9645\u8C61\u68CB\u53EF\u80FD\u662F\u6700\u4F73\u9009\u62E9\u8FD9\u662F\u4E00\u79CD\u9488\u5BF9\u62BD\u8C61\u4E8B\u7269\u7684\u65B9\u5F0F\u8FD8\u6709\u4EBA\u8BA4\u4E3A\u6700\u597D\u7684\u65B9\u6CD5\u662F\u82B1\u94B1\u8D2D\u4E70\u6700\u5148\u8FDB\u7684\u4F20\u611F\u5668\u7136\u540E\u6559\u673A\u5668\u8BF4\u82F1\u8BED\uFF0C\u5C31\u50CF\u6559\u6B63\u5E38\u7684\u5B69\u5B50\u4E00\u6837\uFF0C\u6559\u5B83\u547D\u540D\u4E8B\u7269\u7B49\u7B49\u6211\u4E0D\u77E5\u9053\u6B63\u786E\u7684\u7B54\u6848\uFF0C\u4F46\u6211\u8BA4\u4E3A\u4E24\u8005\u90FD\u503C\u5F97\u5C1D\u8BD5\u4ED6\u4E00\u65B9\u9762\u63D0\u5230\u62BD\u8C61\u7684\u6D3B\u52A8\u5982\u4E0B\u68CB"
  },
  {
    "time": 1902,
    "speaker": "\u6559\u5E08",
    "text": "\u7B2C\u4E8C\u4E2A\u5462\uFF0C\u4ED6\u8BF4\u8981\u8BA9\u673A\u5668\u884C\u52A8\u8D77\u6765\uFF0C\u6709\u4F20\u611F\u80FD\u529B\uFF0C\u80FD\u591F\u770B\u3001\u80FD\u591F\u2026\u2026\u6240\u4EE5\u771F\u7684\u662F\u975E\u5E38\u6709\u8FDC\u89C1\u5353\u8BC6\u6211\u4EEC\u73B0\u5728\u7ECF\u5E38\u542C\u5230\u667A\u80FD\u9886\u57DF\u548C\u8BA4\u77E5\u9886\u57DF\u4E24\u4E2A\u6982\u5FF5\uFF0C\u4E00\u4E2A\u53EB\u5177\u8EAB\u667A\u80FD\u4E00\u4E2A\u53EB\u975E\u5177\u8EAB\u667A\u80FD\uFF0C\u5176\u5B9E\u4E5F\u662F\u8FD9\u4E2A\u65B9\u5411\u5177\u8EAB\u667A\u80FD\u662F\u6307\u667A\u80FD\u4F53\u7684\u667A\u80FD\u4E0D\u4EC5\u4F9D\u8D56\u4E8E\u5927\u8111\u8FD8\u4F9D\u8D56\u4E8E\u8EAB\u4F53\u53CA\u5176\u6240\u5904\u7684\u73AF\u5883\uFF0C\u4E5F\u5C31\u662F\u6211\u4EEC\u7684\u667A\u80FD\u5E76\u975E\u4EC5\u4EC5\u662F\u5927\u8111\u7684\u601D\u7EF4"
  },
  {
    "time": 1934,
    "speaker": "\u6559\u5E08",
    "text": "\u6301\u8FD9\u7C7B\u89C2\u70B9\u7684\u4EBA\u4ED6\u4EEC\u8BA4\u4E3A\u8EAB\u4F53\u4E0E\u73AF\u5883\u7684\u4E92\u52A8\u4E5F\u80FD\u4EA7\u751F\u667A\u80FD\uFF0C\u7136\u540E\u662F\u975E\u5177\u8EAB\u667A\u80FD\u5B83\u8BA4\u4E3A\u4E3B\u8981\u662F\u5927\u8111\u5185\u90E8\u7684\u8BA1\u7B97\u548C\u63A8\u7406\uFF0C\u8FD9\u4E24\u8005\u7684\u533A\u522B\u662F\u4EC0\u4E48\u5462\u5982\u679C\u843D\u5B9E\u5230\u4EBA\u5DE5\u667A\u80FD\u5177\u4F53\u7684\u7814\u7A76\u4E0A\u975E\u5177\u8EAB\u667A\u80FD\u5728\u5185\u90E8\u8FDB\u884C\u8BA1\u7B97\u548C\u63A8\u7406\u65F6\u5B83\u5C31\u50CF\u4E00\u4E2A\u51FD\u6570y=f\uFF0C\u4F60\u7ED9\u5B9Ax\uFF0C\u5C31\u80FD\u8BA1\u7B97\u51FA\u6765"
  },
  {
    "time": 1969,
    "speaker": "\u6559\u5E08",
    "text": "\u4F46\u662F\u5B83\u662F\u5426\u80FD\u89E3\u51B3\u672A\u6765\u7684\u4E8B\u7269\uFF0C\u6211\u4EEC\u4E0D\u5173\u5FC3\u6240\u4EE5\u5F53\u6211\u6309\u7167\u975E\u5177\u8EAB\u667A\u80FD\u7684\u65B9\u5F0F\u8FDB\u884C\u8FD0\u7B97\u65F6\uFF0C\u6211\u4F1A\u7ED9\u51FA\u7ED3\u679C\u4F46\u6211\u7684\u89C2\u70B9\u662F\u5426\u80FD\u89E3\u51B3\u95EE\u9898\uFF0C\u662F\u5426\u6B63\u786E\uFF0C\u6211\u4E0D\u5173\u6CE8\u800C\u5177\u8EAB\u667A\u80FD\u66F4\u5173\u6CE8\u4E92\u52A8\u4E0E\u53CD\u9988\uFF0C\u6240\u4EE5\u8FD9\u662F\u8FD9\u4E24\u7C7B\u7684\u601D\u8DEF\u90A3\u4E48\u5F88\u591A\u4EBA\u5BF9\u8FD9\u4E2A\u6982\u5FF5\u6709\u4E0D\u540C\u7684\u7406\u89E3"
  },
  {
    "time": 2001,
    "speaker": "\u6559\u5E08",
    "text": "\u5C31\u50CF\u6211\u4EEC\u521A\u624D\u8BF4\u7684\u65B0\u4E00\u4EE3\u4FE1\u606F\u6280\u672F\uFF0C\u5C31\u50CF\u65B0\u4E00\u4EE3\u4EBA\u5DE5\u667A\u80FD\u4EBA\u5DE5\u667A\u80FD\u6C38\u8FDC\u662F\u9886\u5148\u4E8E\u65F6\u4EE3\u7684\u6982\u5FF5\u90A3\u4E48\u4EC0\u4E48\u662F\u4EBA\u5DE5\u667A\u80FD\u5176\u5B9E\u4E0D\u91CD\u8981\uFF0C\u91CD\u8981\u7684\u662F\u4EE5\u4F60\u5B9A\u4E49\u7684\u5B83\u4E3A\u76EE\u6807\u53BB\u7814\u7A76\u4E8B\u7269\u603B\u7ED3\u4E0B\u6765\u5927\u6982\u6709\u56DB\u7C7B\uFF0C\u7B2C\u4E00\u7C7B\u662F\u50CF\u4EBA\u4E00\u6837\u884C\u52A8\u7B2C\u4E8C\u7C7B\u662F\u50CF\u4EBA\u4E00\u6837\u601D\u8003\u7B2C\u4E09\u7C7B\u662F\u5408\u7406\u5730\u50CF\u4EBA\u4E00\u6837\u884C\u52A8\uFF0C\u5C31\u662F\u8BA9\u673A\u5668\u6267\u884C\u4EBA\u4E00\u6837\u7684\u52A8\u4F5C"
  },
  {
    "time": 2038,
    "speaker": "\u6559\u5E08",
    "text": "\u4F8B\u5982\u4E0B\u68CB\u65F6\u505A\u51FA\u8FF7\u60D1\u5BF9\u624B\u7684\u52A8\u4F5C\u6BD4\u5982\u4E3E\u68CB\u4E0D\u5B9A\uFF0C\u5047\u88C5\u601D\u8003\u6211\u660E\u660E\u77E5\u9053\u7B54\u6848\uFF0C\u5374\u5047\u88C5\u601D\u8003\uFF0C\u5BF9\u5427\u505A\u51FA\u8FF7\u60D1\u7684\u52A8\u4F5C\uFF0C\u5178\u578B\u7684\u4E8B\u4F8B\u6709\u56FE\u7075\u6D4B\u8BD5\u8FD8\u6709\u521A\u624D\u8BF4\u7684\u90A3\u79CD\u804A\u5929\u673A\u5668\u4EBA\uFF0C\u4ECE\u884C\u4E3A\u4E0A\u770B\uFF0C\u4F60\u80FD\u8BF4\u5B83\u662F\u4EBA\u5417\u50CF\u4EBA\u4E00\u6837\u601D\u8003\uFF0C\u5C31\u662F\u8981\u6253\u5F00\u5916\u9762\u7684\u9ED1\u7BB1\u770B\u5230\u91CC\u9762\u7684\u60C5\u51B5"
  },
  {
    "time": 2069,
    "speaker": "\u6559\u5E08",
    "text": "\u4EE5\u68CB\u7C7B\u6E38\u620F\u6765\u8BF4\uFF0C\u4F60\u8981\u8003\u8651\u5BF9\u624B\u7684\u53CD\u5E94\uFF0C\u6839\u636E\u7ECF\u9A8C\u548C\u76F4\u89C9\u6765\u9009\u62E9\u4E0B\u4E00\u6B65\uFF0C\u4EBA\u662F\u8FD9\u6837\u6839\u636E\u7ECF\u9A8C\u548C\u76F4\u89C9\u4E0B\u68CB\u7684\uFF0C\u7136\u540E\u50CF\u8BA4\u77E5\u6A21\u578B\u795E\u7ECF\u7F51\u7EDC\u6211\u4EEC\u90FD\u5728\u6A21\u62DF\u4EBA\u7684\u601D\u8003\u3001\u4EBA\u7684\u5927\u8111\u7B2C\u4E09\u4E2A\u662F\u5408\u7406\u5730\u884C\u52A8\uFF0C\u5C31\u50CF\u6211\u4EEC\u5B66\u5F88\u591A\u6570\u5B66\u6216\u4F18\u5316\u7406\u8BBA\u4E00\u6837\u5B83\u5176\u5B9E\u6709\u4E00\u4E2A\u76EE\u6807\u51FD\u6570\uFF0C\u57FA\u4E8E\u4E00\u4E2A\u76EE\u6807\u505A\u4F18\u5316\u4F8B\u5982\u4E0B\u68CB\u65F6\u505A\u51FA\u6700\u4F18\u51B3\u7B56\uFF0C\u53EA\u8981\u4F60\u7ED9\u5B9A\u4E00\u79CD\u4E0B\u68CB\u7684\u5224\u522B\u65B9\u5F0F"
  },
  {
    "time": 2105,
    "speaker": "\u6559\u5E08",
    "text": "\u6BD4\u5982\u8F66\u6BD4\u9A6C\u5927\u3001\u9A6C\u6BD4\u76F8\u5927\uFF0C\u4F60\u7ED9\u51FA\u8FD9\u6837\u7684\u89C4\u5219\uFF0C\u90A3\u6211\u5C31\u4F1A\u9075\u5FAA\u4F46\u6709\u7684\u65F6\u5019\u8BE5\u820D\u5F03\u5C31\u820D\u5F03\uFF0C\u6CA1\u6709\u522B\u7684\u529E\u6CD5\u4F46\u662F\u4E0B\u68CB\u5FC5\u987B\u6709\u4E00\u4E2A\u51FD\u6570\u5728\u5176\u4E2D\uFF0C\u8FD9\u5C31\u662F\u5408\u7406\u5730\u884C\u52A8\u8FD9\u6837\u7684\u65B9\u5F0F\u5F80\u5F80\u610F\u5473\u7740\u673A\u5668\u662F\u670D\u52A1\u4E8E\u4EBA\u7684\u5B83\u6309\u7167\u6211\u5B9A\u4E49\u7684\u5408\u7406\u65B9\u5F0F\u53BB\u884C\u52A8\u6240\u4EE5\u667A\u80FD\u4EE3\u7406\u3001\u5DE5\u4E1A\u673A\u5668\u4EBA\u90FD\u662F\u5982\u6B64\u5982\u679C\u4F60\u5E0C\u671B\u8BA1\u7B97\u673A\u671D\u8FD9\u4E2A\u65B9\u5411\u53D1\u5C55\uFF0C\u90A3\u5B83\u6C38\u8FDC\u662F\u4F60\u7684\u52A9\u624B"
  },
  {
    "time": 2137,
    "speaker": "\u6559\u5E08",
    "text": "\u628A\u4F60\u5B9A\u4E49\u6E05\u695A\u7684\u4E8B\u60C5\u4EA4\u7ED9\u5B83\u53BB\u505A\u7B2C\u56DB\u4E2A\u662F\u5408\u7406\u5730\u601D\u8003\u4E5F\u662F\u57FA\u4E8E\u5F62\u5F0F\u903B\u8F91\u548C\u6570\u5B66\u6A21\u578B\u6765\u8BA1\u7B97\u6BD4\u5982\u8BA1\u7B97\u6240\u6709\u7684\u8D70\u6CD5\uFF0C\u7136\u540E\u9009\u62E9\u6700\u4F18\u7B56\u7565\uFF0C\u8FDB\u884C\u7A77\u5C3D\u5F0F\u641C\u7D22\u50CF\u6211\u4EEC\u8BF4\u7684\u4E13\u5BB6\u7CFB\u7EDF\u3001\u51B3\u7B56\u652F\u6301\u7CFB\u7EDF\u3001\u91CF\u5316\u5206\u6790\u90FD\u662F\u8981\u5904\u7406\u5404\u79CD\u53EF\u80FD\u6027\uFF0C\u8FD8\u6709\u4F9B\u5E94\u94FE\u7684\u7BA1\u7406\uFF0C\u5C31\u50CF\u6211\u4EEC\u505A\u4E00\u9053\u9898"
  },
  {
    "time": 2171,
    "speaker": "\u6559\u5E08",
    "text": "\u5927\u5BB6\u5728\u8BFE\u5802\u4E0A\u7ED9\u51FA\u4E00\u4E2A\u4F60\u8BA4\u53EF\u7684\u4EBA\u5DE5\u667A\u80FD\u7684\u5B9A\u4E49\u6211\u4EEC\u8BF4\u5B9A\u4E49\u4E5F\u662F\u76EE\u6807\u6211\u4EEC\u505A\u8FD9\u9053\u9898\uFF0C\u662F\u5E0C\u671B\u5927\u5BB6\u60F3\u4E00\u60F3\u4F60\u5FC3\u91CC\u5E0C\u671B\u4EBA\u5DE5\u667A\u80FD\u662F\u4EC0\u4E48\u6837\u7684\u6211\u4EEC\u770B\u770B\u5927\u5BB6\u7684\u60C5\u51B5"
  },
  {
    "time": 2210,
    "speaker": "\u6559\u5E08",
    "text": "\u6211\u4EEC\u73B0\u5728\u6709\u5341\u4E5D\u4E2A\u540C\u5B66\u63D0\u4EA4\u4E86\uFF0C\u9009A\u7684\u51E0\u4E4E\u6CA1\u6709\uFF0C\u8FD8\u662F\u5173\u6CE8\u5927\u8111\u3002\u6211\u4EEC\u540C\u5B66\u6BD4\u8F83\u5728\u4E4E\uFF0C\u6240\u4EE5\u6709\u9009\u62E9\u601D\u8003\u6D3E\u7684\u3002\u6211\u4EEC\u8BF4\u8FD9\u4E2A\u975E\u5177\u8EAB\u667A\u80FD\u5C31\u662F\u601D\u8003\u6D3E\u3002\u5DE8\u751F\u667A\u80FD\u662F\u884C\u52A8\u6D3E\uFF0C\u8981\u8DDF\u73AF\u5883\u4EA4\u4E92\uFF0C\u9009\u62E9\u4E09\u5206\u4E4B\u4E8C\u662F\u9009\u62E9\u4E86B\u548CD\u3002\u7136\u540E\u4E09\u5206\u4E4B\u4E00\u9009\u62E9\u4E86\u5408\u7406\u7684\uFF0C\u7136\u540E\u9009\u62E9\u50CF\u4EBA\u4E00\u6837\u601D\u8003\u3002"
  },
  {
    "time": 2241,
    "speaker": "\u6559\u5E08",
    "text": "\u5176\u5B9E\u6211\u4EEC\u5173\u6CE8\u60C5\u611F\uFF0C\u50CF\u4EBA\u4E00\u6837\u601D\u8003\u5C31\u4E0D\u4E00\u5B9A\u5408\u7406\uFF0C\u5BF9\u5427\uFF1F\u5C31\u81F3\u5C11\u672A\u5FC5\u7B26\u5408\u516C\u5171\u89C4\u8303\uFF0C\u4E5F\u672A\u5FC5\u7B26\u5408\u4E2A\u4EBA\u76EE\u6807\u3002\u6211\u4EEC\u672A\u6765\u5176\u5B9E\u5728\u5927\u5BB6\u505A\u4E8B\u60C5\u7684\u8FC7\u7A0B\u4E2D\uFF0C\u90FD\u5E94\u8BE5\u671D\u7740\u8FD9\u4E2A\u65B9\u5411\u53BB\u60F3\u3002\u4E00\u76F4\u60F3\u4E00\u60F3\u81EA\u5DF1\u7684\u76EE\u6807\u662F\u4EC0\u4E48\uFF1F\u90A3\u521A\u624D\u6211\u4EEC\u8BF4\u50CF\u4EBA\u4E00\u6837\u7684\u884C\u52A8\uFF0C\u90A3\u56FE\u7075\u6D4B\u8BD5\u662F\u5178\u578B\u7684\u50CF\u4EBA\u4E00\u6837\u884C\u52A8\u3002\u8FD9\u6837\u7684\uFF0C\u5B83\u7684\u8FD9\u4E2A\u8FC7\u7A0B\u5C31\u662F\u8BA9\u4E00\u4E2A\u4EE3\u7406\u7B54\u9898\u8005\u548C\u4E00\u4E2A\u4EBA\u7C7B\u7684\u88C1\u5224\u5FD7\u613F\u8005\u3002"
  },
  {
    "time": 2277,
    "speaker": "\u6559\u5E08",
    "text": "\u7136\u540E\u53BB\u4E92\u52A8\uFF0C\u770B\u8D77\u6765\u662F\u5728\u8DDF\u4EBA\u6C9F\u901A\u3002\u4F46\u5B9E\u9645\u4E0A\u8FD9\u4E2A\u4EBA\u540E\u8FB9\u85CF\u7740\u4EBA\u6216\u8005\u8BA1\u7B97\u673A\u3002\u90A3\u4E48\u5982\u679C\u4F60\u8BEF\u8BA4\u4E3A\u8FD9\u4E2A\u4EE3\u7406\u7B54\u9898\u8005\u8BF4\u7684\u662F\u8BA1\u7B97\u673A\u7684\u7B54\u6848\u3002\u8BF4\u7684\u662F\u4EBA\u7684\u7B54\u6848\u5176\u5B9E\u662F\u8BA1\u7B97\u673A\uFF0C\u90A3\u8FD9\u79CD\u9519\u8BEF\u7387\u8D85\u8FC730%\u3002\u4E5F\u5C31\u662F\u5341\u6B21\u3002\u4F60\u628A\u8BA1\u7B97\u673A\u731C\u9519\u4E86\u4E09\u6B21\uFF0C\u90FD\u8BA4\u4E3A\u5B83\u662F\u4EBA\uFF0C\u90A3\u5C31\u8BC1\u660E\u5B83\u80FD\u901A\u8FC7\u3002\u4F46\u662F\u5C31\u8FD9\u6837\u7684\u6D4B\u8BD5\uFF0C\u57FA\u672C\u4E0A\u57282000\u5E74\u4E4B\u524D\u6CA1\u6709\u7CFB\u7EDF\u3002"
  },
  {
    "time": 2309,
    "speaker": "\u6559\u5E08",
    "text": "\u73B0\u5728\u8FD9\u7C7B\u5BF9\u8BDD\u7CFB\u7EDF\u5DF2\u7ECF\u5F88\u5E38\u89C1\u4E86\u3002\u6709\u4EBA\u5C31\u628A\u8BB0\u7B14\u8BB0\u521A\u51FA\u6765\u7684\u65F6\u5019\uFF0C\u5F88\u5FEB\u505A\u4E00\u4E2A\u7F51\u9875\uFF0C\u7136\u540E\u8BA9\u4F60\u804A\u5929\u3002\u95EE\u4F60\u73B0\u5728\u8DDF\u8C01\u5728\u804A\u5929\uFF0C\u662F\u4EBA\u8FD8\u662F\u4E00\u4E2AAI\u3002\u90A3\u4E48\u5982\u679C\u771F\u662F\u5728\u8DDF\u4EBA\u804A\u5929\u7684\u65F6\u5019\uFF0C\u90A3\u4F60\u80FD\u731C\u5BF9\uFF0C\u662F\u5427\uFF1F\u5927\u90E8\u5206\u90FD\u5E94\u8BE5\u662F\u731C\u5BF9\u7684\uFF0C\u6709\u76F8\u5F53\u6BD4\u4F8B\u7684\u5224\u65AD\u4F1A\u51FA\u9519\u3002\u7136\u540E\u8FD8\u662F\u731C\u4EBA\u731C\u5F97\u66F4\u51C6\u4E00\u70B9\u3002\u731C\u5230\u8FD9\u4E2A\u673A\u5668\u4EBA\u7684\u65F6\u5019\uFF0C\u54CE\uFF0C\u5927\u90E8\u5206\u8FD8\u662F\u80FD\u731C\u51FA\u6765\u5B83\u662F\u673A\u5668\u4EBA\u3002"
  },
  {
    "time": 2343,
    "speaker": "\u6559\u5E08",
    "text": "\u4F46\u662F\u731C\u9519\u4E8640%\u3002\u90A3\u5C31\u662F\u4F60\u8BA4\u4E3A\u5B83\u4E0D\u662F\u4E00\u4E2A\u673A\u5668\u4EBA\uFF0C\u662F\u4E00\u4E2A\u4EBA\u7C7B\uFF0C\u90A3\u8FD9\u5C31\u901A\u8FC7\u4E8630%\u3002\u6240\u4EE5\u5230\u5F53\u65F6\u624D\u8FBE\u5230\u8FD9\u6837\u3002\u5F53\u7136\u7ECF\u5E38\u4F7F\u62C6\u7684G\u5668\u5462\uFF0C\u5C31\u6709\u4EBA\u4F1A\u89C9\u5F97\u5B83\u5E26\u6709\u673A\u68B0\u611F\uFF0C\u4F60\u5DF2\u7ECF\u5728\u8BC6\u522B\u8FD9\u4E2A\u3002\u8FD9\u662F\u8FD9\u79CD\u7C7B\u578B\u7684\u4EBA\uFF0C\u6240\u4EE5\u90A3\u662F\u53E6\u5916\u4E00\u4E2A\u6982\u5FF5\u3002\u90A3\u6211\u4EEC\u603B\u7ED3\u8FD970\u5E74\u7684\u4EBA\u5DE5\u667A\u80FD\u63A2\u7D22\u3002\u90A3\u4E48\u6574\u4E2A\u7B2C\u4E00\u4EE3\u662F\u77E5\u8BC6\u9A71\u52A8\u3002"
  },
  {
    "time": 2375,
    "speaker": "\u6559\u5E08",
    "text": "\u90A3\u7528\u7B26\u53F7\u53BB\u8868\u793A\u77E5\u8BC6\uFF0C\u80FD\u591F\u8FDB\u884C\u63A8\u7406\u3002\u5B83\u7684\u597D\u5904\u5462\u662F\u53EF\u89E3\uFF0C\u6240\u6709\u7684\u89C4\u5219\u90FD\u5DF2\u7ECF\u8868\u8FBE\u51FA\u6765\uFF0C\u4E0D\u662F\u4F60\u5199\u7684\u3002\u5C31\u662F\u4F60\u7684\u7956\u8F88\u5199\u7684\uFF0C\u90FD\u662F\u53EF\u4EE5\u5224\u65AD\u7684\uFF0C\u7F3A\u70B9\u662F\u8D39\u65F6\u8D39\u529B\u3002\u8FD9\u79CD\u89C4\u5219\u4F60\u8981\u5199\u4E0B\u53BB\uFF0C\u4F60\u7684\u5B50\u5B50\u5B59\u5B59\u8FD8\u8981\u5199\u4E0B\u53BB\u3002\u7B2C\u4E8C\u4EE3\u4EBA\u5DE5\u667A\u80FD\u662F\u6570\u636E\u9A71\u52A8\u3002"
  }
];

