// content-accuracy-styles.js
var contentAccuracyStyles = `
.ca-section .attitude-insight{margin-bottom:20px}
.ca-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
.ca-card{min-width:0;text-align:left;border:1px solid var(--border);border-radius:8px;background:#fcfdff;padding:18px 20px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:7px 16px;align-items:start}
.ca-card:hover{background:#f4f8ff;border-color:#bed6fc;box-shadow:0 5px 16px #1d70f20d}
.ca-card h3{font-size:14px;line-height:24px;color:var(--primary)}
.ca-card p{grid-column:1 / -1;font-size:13px;line-height:22px;color:var(--secondary)}
.ca-status{font-size:12px;line-height:22px;padding:0 8px;border-radius:4px;color:#c47732;background:#fff6ea;border:1px solid #f0d2ae;white-space:nowrap}
.ca-dialog{width:760px;max-width:calc(100% - 32px);max-height:86vh}
.ca-head{padding:23px 28px 18px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--border)}
.ca-head h2{font-size:21px;line-height:32px;color:var(--primary)}
.ca-close{width:32px;height:32px;border-radius:50%;font-size:24px;line-height:28px;color:#939aa8}
.ca-close:hover{background:#f0f3fc}
.ca-body{padding:22px 28px 28px;overflow:auto}
.ca-lead{display:flex;align-items:center;gap:10px;margin-bottom:18px}
.ca-lead strong{font-size:16px;color:var(--primary)}
.ca-meta{font-size:12px;color:var(--muted);margin-bottom:8px}
.ca-block{padding:15px 17px;border:1px solid var(--border);border-radius:8px;background:#fcfdff;margin-top:12px}
.ca-block h3{font-size:14px;line-height:24px;color:var(--primary);margin:0 0 6px}
.ca-block p{font-size:13px;line-height:23px;color:var(--secondary);margin:0}
.ca-quote{border-left:3px solid var(--blue);background:#f5f8ff}
.ca-quote p{color:var(--primary)}
.ca-context{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.ca-context .ca-block{margin-top:0}
.ca-formula{font-variant-numeric:tabular-nums}
.ca-dialog mark{background:#fff0b8;color:inherit;padding:1px 2px}
@media(max-width:700px){.ca-grid,.ca-context{grid-template-columns:1fr}.ca-card{padding:16px}.ca-head{padding:18px 20px 14px}.ca-body{padding:18px 20px 22px}.ca-head h2{font-size:18px}.ca-dialog{max-width:calc(100% - 20px)}}
@media print{.ca-card{break-inside:avoid}.ca-dialog{display:none!important}}
`;

// content-accuracy.js
var esc22 = (value) => String(value ?? "").replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char]);
function mountContentAccuracy(root) {
  if (!root || contentAccuracyVersion === "baseline") return () => {
  };
  const challenges = root.querySelector("#content-challenges");
  if (!challenges || root.querySelector("#content-accuracy")) return () => {
  };
  const style = document.createElement("style");
  style.dataset.contentAccuracyStyle = "";
  style.textContent = contentAccuracyStyles;
  document.head.append(style);
  const section3 = document.createElement("section");
  section3.className = "card section ca-section";
  section3.id = "content-accuracy";
  section3.setAttribute("aria-labelledby", "content-accuracy-title");
  section3.innerHTML = `<div class="section-heading"><h2 id="content-accuracy-title">\u77E5\u8BC6\u51C6\u786E\u6027</h2></div><div class="attitude-insight"><img src="assets/figma/content-img111111.svg" width="16" height="16" alt=""><p>${esc22(contentAccuracyData.insight)}</p></div><div class="ca-grid">${contentAccuracyData.items.map((item) => `<button type="button" class="ca-card" data-ca-id="${item.id}" aria-label="${esc22(item.title)}\uFF0C${item.status}\uFF0C\u67E5\u770B\u8BC1\u636E"><h3>${esc22(item.title)}</h3><span class="ca-status">${esc22(item.status)}</span><p>${esc22(item.summary)}</p></button>`).join("")}</div>`;
  challenges.after(section3);
  queueMicrotask(() => {
    const practice = root.querySelector("#content-practice");
    if (section3.isConnected && practice) practice.after(section3);
  });
  const dialog = document.createElement("dialog");
  dialog.className = "ca-dialog";
  dialog.setAttribute("aria-labelledby", "ca-dialog-title");
  document.body.append(dialog);
  let trigger = null, scrollY2 = 0, previousOverflow = "";
  function close() {
    if (dialog.open) dialog.close();
  }
  function open(button4, item) {
    trigger = button4;
    scrollY2 = window.scrollY;
    previousOverflow = document.body.style.overflow;
    dialog.innerHTML = `<header class="ca-head"><h2 id="ca-dialog-title">${esc22(item.title)}</h2><button type="button" class="ca-close" aria-label="\u5173\u95ED">\xD7</button></header><div class="ca-body"><div class="ca-lead"><strong>\u77E5\u8BC6\u8868\u8FF0\u6838\u67E5</strong><span class="ca-status">${esc22(item.status)}</span></div><div class="ca-block ca-quote"><div class="ca-meta">${esc22(item.time)} \xB7 ${esc22(item.speaker)}</div><h3>\u6559\u5E08\u539F\u8BDD</h3><p>\u201C${esc22(item.quote)}\u201D</p></div><h3 style="margin:18px 0 10px;font-size:14px">\u4E0A\u4E0B\u6587</h3><div class="ca-context"><div class="ca-block"><h3>\u524D\u6587</h3><p>${esc22(item.before)}</p></div><div class="ca-block"><h3>\u540E\u6587</h3><p>${esc22(item.after)}</p></div></div><div class="ca-block ca-formula"><h3>\u8BFE\u4EF6\u516C\u5F0F\u5BF9\u7167</h3><p>${esc22(item.slide)}</p></div><div class="ca-block"><h3>\u5F85\u6838\u67E5\u5224\u65AD</h3><p>${esc22(item.judgment)}</p></div><div class="ca-block"><h3>\u4FEE\u6B63\u5EFA\u8BAE</h3><p>${esc22(item.suggestion)}</p></div></div>`;
    dialog.querySelector(".ca-close").addEventListener("click", close);
    document.body.style.overflow = "hidden";
    dialog.showModal();
    dialog.querySelector(".ca-close").focus({ preventScroll: true });
  }
  section3.addEventListener("click", (event) => {
    const button4 = event.target.closest("[data-ca-id]");
    if (!button4) return;
    const item = contentAccuracyData.items.find((entry2) => entry2.id === button4.dataset.caId);
    if (item) open(button4, item);
  });
  dialog.addEventListener("cancel", (event) => {
    event.preventDefault();
    close();
  });
  dialog.addEventListener("click", (event) => {
    if (event.target !== dialog) return;
    const box = dialog.getBoundingClientRect();
    if (event.clientX < box.left || event.clientX > box.right || event.clientY < box.top || event.clientY > box.bottom) close();
  });
  dialog.addEventListener("close", () => {
    document.body.style.overflow = previousOverflow;
    window.scrollTo(0, scrollY2);
    trigger?.focus({ preventScroll: true });
  });
  return () => {
    close();
    dialog.remove();
    section3.remove();
    style.remove();
  };
}

