function mountChallengeMatch(root, { openDialog: openDialog2 }) {
  if (location.pathname.includes("/previews/")) return;
  const section3 = root.querySelector("#content-challenges");
  if (!section3 || section3.querySelector("[data-challenge-match]")) return;
  const score2 = Math.round(challengeMatches.reduce((s, r) => s + r.score, 0) / challengeMatches.length);
  const wrap = document.createElement("div");
  wrap.className = "ccm-heading";
  wrap.innerHTML = `<button type="button" data-challenge-match aria-label="\u6559\u5B66\u91CD\u96BE\u70B9\u5927\u7EB2\u5339\u914D\u5EA6${score2}%\uFF0C\u67E5\u770B\u5BF9\u7167">\u5927\u7EB2\u5339\u914D\u5EA6 <strong>${score2}<small>%</small></strong></button><span class="ccm-help"><button type="button" aria-label="\u6559\u5B66\u91CD\u96BE\u70B9\u5927\u7EB2\u5339\u914D\u5EA6\u5B9A\u4E49" aria-expanded="false">?</button><span>\u4EE5\u672C\u8BFE\u5BF9\u5E94\u7684\u5927\u7EB2\u8981\u6C42\u4E3A\u53C2\u7167\uFF0C\u89C2\u5BDF\u91CD\u96BE\u70B9\u8BBE\u7F6E\u662F\u5426\u5BF9\u5E94\u5173\u952E\u5185\u5BB9\u4E0E\u8981\u6C42\u5C42\u6B21\u3002\u6761\u76EE\u7B49\u6743\u6C47\u603B\uFF0C\u672A\u5217\u5165\u8981\u6C42\u8BA10\uFF0C\u62D3\u5C55\u5185\u5BB9\u4E0D\u62B5\u6D88\u9057\u6F0F\uFF1B\u4E0D\u4EE3\u8868\u8BFE\u5802\u8BB2\u6388\u8986\u76D6\u7387\u6216\u5B66\u751F\u638C\u63E1\u7A0B\u5EA6\u3002</span></span>`;
  section3.querySelector(".section-heading").append(wrap);
  const style = document.createElement("style");
  style.textContent = `#content-challenges .ccm-heading{display:flex;gap:8px;align-items:center}#content-challenges [data-challenge-match]{border:0;background:transparent;cursor:pointer;font:13px/24px inherit;font-family:inherit;color:var(--muted);padding:0}#content-challenges [data-challenge-match] strong{font-size:20px;color:#1d70f2;font-weight:600;margin-left:8px}#content-challenges [data-challenge-match] small{font-size:12px;margin-left:2px}#content-challenges .ccm-help{position:relative;display:inline-flex}#content-challenges .ccm-help>button{width:16px;height:16px;border:1px solid var(--supplementary);color:var(--muted);border-radius:50%;font:11px/14px sans-serif;padding:0;background:transparent;cursor:pointer}#content-challenges .ccm-help>span{display:none;position:absolute;right:0;top:24px;width:300px;max-width:70vw;font-size:12px;line-height:22px;padding:12px 14px;background:white;border:1px solid var(--border);border-radius:8px;box-shadow:0 4px 16px #24324718;z-index:5;color:var(--secondary)}#content-challenges .ccm-help:hover>span,#content-challenges .ccm-help:focus-within>span,#content-challenges .ccm-help.is-open>span{display:block}#content-challenges :focus-visible{outline:2px solid #1d70f2;outline-offset:3px}#detail-dialog .ccm-record{padding:20px 0;border-top:1px solid var(--border)}#detail-dialog .ccm-record h3{font-size:16px;line-height:26px;margin:0 0 10px}#detail-dialog .ccm-record p{font-size:14px;line-height:24px}#detail-dialog .ccm-record small{font-size:12px;color:var(--muted)}#detail-dialog .ccm-source{background:#f5f8fd;padding:12px 14px;border-radius:8px}#detail-dialog .ccm-summary{font-size:14px;line-height:24px;color:var(--secondary)}@media(max-width:600px){#content-challenges>.section-heading{flex-wrap:wrap;gap:12px}#content-challenges .ccm-heading{margin-left:auto}}`;
  style.textContent = style.textContent.replace("font:13px/24px inherit", "font-size:13px;line-height:24px");
  document.head.append(style);
  const dialog = document.getElementById("detail-dialog");
  let trigger, scroll;
  wrap.querySelector("[data-challenge-match]").addEventListener("click", (e) => {
    trigger = e.currentTarget;
    scroll = { x: scrollX, y: scrollY };
    openDialog2("\u6559\u5B66\u91CD\u96BE\u70B9 \xB7 \u5927\u7EB2\u5339\u914D\u5EA6", `<p class="ccm-summary"><strong>\u5927\u7EB2\u5339\u914D\u5EA6 ${score2}%</strong><br>${esc23(goalsData.outline)} \xB7 ${esc23(goalsData.scope)}<br>\u4E09\u9879\u8981\u6C42\u7B49\u6743\uFF1A\uFF0890%\uFF0B80%\uFF0B0%\uFF09\xF73\u224857%\u3002\u6309\u5927\u7EB2\u8981\u6C42\u6838\u5BF9\uFF0C\u91CD\u590D\u5217\u51FA\u7684\u540C\u4E00\u91CD\u96BE\u70B9\u4E0D\u91CD\u590D\u52A0\u5206\u3002</p>${challengeMatches.map((r) => `<article class="ccm-record"><h3>${r.indices.length ? "\u90E8\u5206\u5339\u914D" : "\u672A\u5217\u5165"} \xB7 ${r.score}%</h3><small>\u5927\u7EB2\u8981\u6C42 \xB7 \u7B2C${r.page}\u9875</small><p class="ccm-source">${esc23(r.requirement)}</p><small>\u5BF9\u5E94\u91CD\u96BE\u70B9</small><p>${r.indices.length ? esc23(contentData.challenges[r.indices[0]]) : "\u5F53\u524D\u91CD\u96BE\u70B9\u5217\u8868\u672A\u627E\u5230\u5BF9\u5E94\u5185\u5BB9\u3002"}</p><p>${esc23(r.reason)}</p></article>`).join("")}<article class="ccm-record"><h3>\u62D3\u5C55\u5185\u5BB9</h3><p>${esc23(contentData.challenges[1])}</p><p>\u5F53\u524D\u4E09\u9879\u5927\u7EB2\u8981\u6C42\u4E2D\u6CA1\u6709\u76F4\u63A5\u5BF9\u5E94\u6761\u76EE\uFF0C\u4FDD\u7559\u5176\u62D3\u5C55\u4EF7\u503C\uFF0C\u4E0D\u8BA1\u5165\u5339\u914D\u5EA6\uFF0C\u4E5F\u4E0D\u62B5\u6D88\u672A\u5217\u5165\u7684\u8981\u6C42\u3002</p></article>`, "\u6559\u5B66\u5185\u5BB9 / \u6559\u5B66\u91CD\u96BE\u70B9");
  });
  wrap.querySelector(".ccm-help>button").addEventListener("click", (e) => {
    const open = e.currentTarget.getAttribute("aria-expanded") !== "true";
    e.currentTarget.setAttribute("aria-expanded", open);
    e.currentTarget.parentElement.classList.toggle("is-open", open);
  });
  dialog.addEventListener("close", () => {
    if (dialog.open || !trigger) return;
    const target = trigger;
    trigger = null;
    target.focus({ preventScroll: true });
    window.scrollTo({ left: scroll.x, top: scroll.y, behavior: "instant" });
  });
}

