  <section class="card section" id="attitude-patrol" aria-labelledby="patrol-title">${sectionHead("patrol", "\u5DE1\u5802\u8F68\u8FF9")}${insight("\u8BB2\u53F0\u533A\u8C03\u5EA6\u81EA\u5982\u4F53\u73B0\u6559\u5B66\u8282\u594F\u638C\u63A7\u529B\uFF0C\u5B66\u751F\u533A\u4ECB\u5165\u7A0D\u663E\u4E0D\u8DB3\uFF1B\u5EFA\u8BAE\u589E\u52A0\u4E2A\u6027\u5316\u6307\u5BFC\u9891\u7387\u4EE5\u5F3A\u5316\u8D70\u52A8\u4E92\u52A8\u7684\u6DF1\u5EA6\u8986\u76D6\u3002")}${patrolChart()}</section>
