  const paths = model.keypoints.map((_, i) => `<path d="M0 ${height / 2} C28 ${height / 2} 22 ${i * 88 + 38} 50 ${i * 88 + 38}"/>`).join("");
  const tree = document.createElement("div");
  tree.className = "cg-map";
